package lint

import (
	"go/ast"
	"go/token"
)

// Severity is the level of a failure.
type Severity string

const (
	// SeverityWarning marks a failure as a warning.
	SeverityWarning Severity = "warning"
	// SeverityError marks a failure as an error.
	SeverityError Severity = "error"
)

// FailurePosition holds the start and end of a failure.
type FailurePosition struct {
	Start token.Position
	End   token.Position
}

// Failure describes a single lint problem.
type Failure struct {
	Severity        Severity
	Failure         string
	RuleName        string
	Category        string
	Position        FailurePosition
	Confidence      float64
	ReplacementLine string
	Node            ast.Node `json:"-"`
}

// GetFilename returns the name of the file where the failure was found.
func (f *Failure) GetFilename() string {
	return f.Position.Start.Filename
}

// IsInternal reports whether this failure was produced by the engine itself.
func (f *Failure) IsInternal() bool {
	return f.Category == internalCategory
}

const internalCategory = "REVIVE_INTERNAL"

// NewInternalFailure builds a failure that signals an internal problem.
func NewInternalFailure(msg string) Failure {
	return Failure{
		Category: internalCategory,
		Failure:  msg,
	}
}

// DisabledInterval is a range of lines where a rule is disabled.
type DisabledInterval struct {
	From     token.Position
	To       token.Position
	RuleName string
}

// Arguments are the arguments passed to a rule.
type Arguments []any

// RuleConfig is the per-rule configuration.
type RuleConfig struct {
	Arguments Arguments
	Severity  Severity
	Disabled  bool
	Exclude   []string

	excludeFilters []*FileFilter
}

// Initialize prepares the rule configuration (compiles file filters).
func (rc *RuleConfig) Initialize() error {
	for _, f := range rc.Exclude {
		ff, err := ParseFileFilter(f)
		if err != nil {
			return err
		}
		rc.excludeFilters = append(rc.excludeFilters, ff)
	}
	return nil
}

// MustExclude reports whether the file must be skipped for this rule.
func (rc *RuleConfig) MustExclude(name string) bool {
	for _, ff := range rc.excludeFilters {
		if ff.MatchFileName(name) {
			return true
		}
	}
	return false
}

// RulesConfig maps rule names to their configuration.
type RulesConfig map[string]RuleConfig

// DirectiveConfig is the configuration of a directive.
type DirectiveConfig struct {
	Severity Severity
}

// DirectivesConfig maps directive names to their configuration.
type DirectivesConfig map[string]DirectiveConfig

// Config is the global configuration.
type Config struct {
	IgnoreGeneratedHeader bool
	Confidence            float64
	Severity              Severity
	EnableAllRules        bool
	Rules                 RulesConfig
	ErrorCode             int
	WarningCode           int
	Directives            DirectivesConfig
	Exclude               []string
}
EOF
echo ok"}

