package lint

import (
	"fmt"
	"regexp"
	"strings"
)

// FileFilter decides whether a file name matches a configured pattern.
// Supported pattern flavours:
//   - plain paths: pkg/mypkg/my.go
//   - globs with * and **: **/*.pb.go
//   - regular expressions prefixed by ~: ~-tmp\.\d+\.go
//   - the special marker TEST which matches test files
type FileFilter struct {
	raw            string
	rx             *regexp.Regexp
	matchesAll     bool
	matchesNothing bool
}

// ParseFileFilter builds a filter out of its textual form.
func ParseFileFilter(raw string) (*FileFilter, error) {
	raw = strings.TrimSpace(raw)
	ff := &FileFilter{raw: raw}
	ff.matchesNothing = raw == ""
	ff.matchesAll = raw == "*" || raw == "~"
	if !ff.matchesAll && !ff.matchesNothing {
		if err := ff.compile(); err != nil {
			return nil, err
		}
	}
	return ff, nil
}

func (ff *FileFilter) String() string { return ff.raw }

// MatchFileName reports whether the given file name matches the filter.
func (ff *FileFilter) MatchFileName(name string) bool {
	if ff.matchesAll {
		return true
	}
	if ff.matchesNothing {
		return false
	}
	name = strings.ReplaceAll(name, "\\", "/")
	return ff.rx.MatchString(name)
}

var (
	badDoubleStar = regexp.MustCompile(`[^/]\*\*[^/]`)
	regexSpecials = ".+{}()[]^$"
)

func (ff *FileFilter) compile() error {
	src := ff.raw
	if src == "TEST" {
		src = `~_test\.go`
	}
	if strings.HasPrefix(src, "~") {
		rx, err := regexp.Compile(src[1:])
		if err != nil {
			return fmt.Errorf("invalid file filter [%s], regexp compile error: [%v]", ff.raw, err)
		}
		ff.rx = rx
		return nil
	}
	if strings.Contains(src, "*") {
		if badDoubleStar.MatchString(src) {
			return fmt.Errorf("invalid file filter [%s], invalid glob pattern", ff.raw)
		}
		var sb strings.Builder
		sb.WriteByte('^')
		pendingStar := false
		afterDirGlob := false
		for _, c := range src {
			if c == '*' {
				if pendingStar {
					sb.WriteString(`[\s\S]*`)
					pendingStar = false
					afterDirGlob = true
					continue
				}
				pendingStar = true
				continue
			}
			if pendingStar {
				sb.WriteString(`[^/]*`)
				pendingStar = false
			}
			if strings.ContainsRune(regexSpecials, c) {
				sb.WriteByte('\\')
			}
			sb.WriteRune(c)
			if c == '/' && afterDirGlob {
				sb.WriteByte('?')
			}
			afterDirGlob = false
		}
		if pendingStar {
			sb.WriteString(`[^/]*`)
		}
		sb.WriteByte('$')
		rx, err := regexp.Compile(sb.String())
		if err != nil {
			return fmt.Errorf("invalid file filter [%s], regexp compile error after glob expand: [%v]", ff.raw, err)
		}
		ff.rx = rx
		return nil
	}
	full := strings.ReplaceAll(src, "\\", "/")
	full = strings.ReplaceAll(full, ".", `\.`)
	rx, err := regexp.Compile("^" + full + "$")
	if err != nil {
		return fmt.Errorf("invalid file filter [%s], regexp compile full path: [%v]", ff.raw, err)
	}
	ff.rx = rx
	return nil
}
EOF
echo done"}

