package lint

import (
	"bytes"
	"go/ast"
	"go/parser"
	"go/printer"
	"go/token"
	"go/types"
	"math"
	"regexp"
	"strings"
)

// File is a Go source file being linted.
type File struct {
	Name    string
	Pkg     *Package
	content []byte
	AST     *ast.File
}

// NewFile parses the given content and builds a File.
func NewFile(name string, content []byte, pkg *Package) (*File, error) {
	f, err := parser.ParseFile(pkg.fset, name, content, parser.ParseComments)
	if err != nil {
		return nil, err
	}
	return &File{
		Name:    name,
		content: content,
		Pkg:     pkg,
		AST:     f,
	}, nil
}

// ToPosition converts a token.Pos into a token.Position.
func (f *File) ToPosition(pos token.Pos) token.Position {
	return f.Pkg.fset.Position(pos)
}

// Render pretty-prints the given node.
func (f *File) Render(x any) string {
	var buf bytes.Buffer
	if err := printer.Fprint(&buf, f.Pkg.fset, x); err != nil {
		panic(err)
	}
	return buf.String()
}

// CommentMap returns the comment map of the file.
func (f *File) CommentMap() ast.CommentMap {
	return ast.NewCommentMap(f.Pkg.fset, f.AST, f.AST.Comments)
}

// Content returns the raw content of the file.
func (f *File) Content() []byte {
	return f.content
}

// IsTest reports whether the file is a test file.
func (f *File) IsTest() bool {
	return strings.HasSuffix(f.Name, "_test.go")
}

// IsUntypedConst reports whether expr is an untyped constant and indicates
// its kind.
func (f *File) IsUntypedConst(expr ast.Expr) (defType string, ok bool) {
	t := f.Pkg.TypeOf(expr)
	if t == nil {
		return "", false
	}
	b, ok := t.(*types.Basic)
	if !ok {
		return "", false
	}
	if b.Info()&types.IsUntyped == 0 {
		return "", false
	}
	switch b.Kind() {
	case types.UntypedBool:
		return "bool", true
	case types.UntypedInt:
		return "int", true
	case types.UntypedRune:
		return "rune", true
	case types.UntypedFloat:
		return "float64", true
	case types.UntypedComplex:
		return "complex128", true
