		for _, name := range ruleNames {
			switch modifier {
			case modifierLine:
				handleConfig(isEnabled, line, name)
				handleConfig(!isEnabled, line, name)
			case modifierNextLine:
				handleConfig(isEnabled, line+1, name)
				handleConfig(!isEnabled, line+1, name)
