package lint

import (
	"errors"
	"go/ast"
	"go/importer"
	"go/token"
	"go/types"
	"sync"
)

// Package is a set of files belonging to the same Go package.
type Package struct {
	fset  *token.FileSet
	files map[string]*File

	typesPkg  *types.Package
	typesInfo *types.Info

	// sortable types in this package (implementing sort.Interface)
	sortable map[string]bool
	// main is 1 if the package is a main package, -1 if it is not, 0 if unknown
	main int
	mu   sync.Mutex
}

var (
	trueValue  = 1
	falseValue = 2
	notSet     = 3
)

// Files returns the files of the package.
func (p *Package) Files() map[string]*File {
	return p.files
}

// IsMain reports whether the package is a main package.
func (p *Package) IsMain() bool {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.main == trueValue {
		return true
	} else if p.main == falseValue {
		return false
	}
	for _, f := range p.files {
		if f.isMain() {
			p.main = trueValue
			return true
		}
	}
	p.main = falseValue
	return false
}

// TypesPkg returns the types package.
func (p *Package) TypesPkg() *types.Package {
	p.mu.Lock()
	defer p.mu.Unlock()
	return p.typesPkg
}

// TypesInfo returns the type information.
func (p *Package) TypesInfo() *types.Info {
	p.mu.Lock()
	defer p.mu.Unlock()
	return p.typesInfo
}

// Sortable returns the set of sortable types.
func (p *Package) Sortable() map[string]bool {
	p.mu.Lock()
	defer p.mu.Unlock()
	return p.sortable
}

// TypeCheck runs the type checker over the package, ignoring errors.
func (p *Package) TypeCheck() error {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.typesInfo != nil || p.typesPkg != nil {
		return nil
	}
	config := &types.Config{
		Importer: importer.Default(),
		Error:    func(error) {},
		Sizes:    types.SizesFor("gc", "amd64"),
	}
	info := &types.Info{
		Types:  make(map[ast.Expr]types.TypeAndValue),
		Defs:   make(map[*ast.Ident]types.Object),
		Uses:   make(map[*ast.Ident]types.Object),
		Scopes: make(map[ast.Node]*types.Scope),
	}
	var anyFile *File
	var astFiles []*ast.File
	for _, f := range p.files {
		anyFile = f
		astFiles = append(astFiles, f.AST)
	}
	if anyFile == nil {
		return errors.New("no files")
	}
	typesPkg, err := check(config, anyFile.AST.Name.Name, p.fset, astFiles, info)
	p.typesPkg = typesPkg
	p.typesInfo = info
	return err
}

func check(config *types.Config, n string, fset *token.FileSet, astFiles []*ast.File, info *types.Info) (p *types.Package, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = errors.New("type checker panic")
			p = nil
		}
	}()
	return config.Check(n, fset, astFiles, info)
}

// TypeOf returns the type of an expression, if known.
func (p *Package) TypeOf(expr ast.Expr) types.Type {
	if p.typesInfo == nil {
		return nil
	}
	return p.typesInfo.TypeOf(expr)
}

type walker struct {
	nmap map[string]int
	has  map[string]int
}

func (w *walker) Visit(n ast.Node) ast.Visitor {
	fn, ok := n.(*ast.FuncDecl)
	if !ok || fn.Recv == nil || len(fn.Recv.List) == 0 {
		return w
	}
	// TODO(dsymonds): We could check the signature to be more precise.
	recv := receiverType(fn)
	if i, ok := w.nmap[fn.Name.Name]; ok {
		w.has[recv] |= i
	}
	return w
}

func receiverType(fn *ast.FuncDecl) string {
	switch e := fn.Recv.List[0].Type.(type) {
	case *ast.Ident:
		return e.Name
	case *ast.StarExpr:
		if id, ok := e.X.(*ast.Ident); ok {
			return id.Name
		}
	}
	return "invalid-type"
}

func (p *Package) scanSortable() {
	p.sortable = make(map[string]bool)

	// bitfield for which methods exist on each type.
	const (
		Len = 1 << iota
		Less
		Swap
	)
	nmap := map[string]int{"Len": Len, "Less": Less, "Swap": Swap}
	has := make(map[string]int)
	for _, f := range p.files {
		ast.Walk(&walker{nmap, has}, f.AST)
	}
	for typ, ms := range has {
		if ms == Len|Less|Swap {
			p.sortable[typ] = true
		}
	}
}

func (p *Package) lint(rules []Rule, config Config, failures chan Failure) {
	p.scanSortable()
	var wg sync.WaitGroup
	for _, file := range p.files {
		wg.Add(1)
		go func(file *File) {
			defer wg.Done()
			if err := file.lint(rules, config, failures); err != nil {
				failures <- NewInternalFailure(err.Error())
			}
		}(file)
	}
	wg.Wait()
}
EOF
echo done"}

