package formatter

import (
	"bytes"
	"fmt"
	"html"
	"sort"

	"revive/lint"
)

// Checkstyle is a formatter producing checkstyle XML.
type Checkstyle struct {
	Metadata lint.FormatterMetadata
}

// Name returns the name of the formatter.
func (*Checkstyle) Name() string {
	return "checkstyle"
}

type checkstyleIssue struct {
	Line       int
	Column     int
	What       string
	Confidence float64
	Severity   lint.Severity
	RuleName   string
}

// Format formats the failures gotten from the lint.
func (*Checkstyle) Format(failures <-chan lint.Failure, _ lint.Config) (string, error) {
	issues := map[string][]checkstyleIssue{}
	var order []string
	for failure := range failures {
		fn := failure.GetFilename()
		if _, ok := issues[fn]; !ok {
			order = append(order, fn)
		}
		issues[fn] = append(issues[fn], checkstyleIssue{
			Line:       failure.Position.Start.Line,
			Column:     failure.Position.Start.Column,
			What:       failure.Failure,
			Confidence: failure.Confidence,
			Severity:   failure.Severity,
			RuleName:   failure.RuleName,
		})
	}
	sort.Strings(order)

	var buf bytes.Buffer
	buf.WriteString("<?xml version='1.0' encoding='UTF-8'?>\n")
	buf.WriteString("<checkstyle version=\"5.0\">\n")
	for _, fn := range order {
		fmt.Fprintf(&buf, "    <file name=\"%s\">\n", html.EscapeString(fn))
		for _, is := range issues[fn] {
			fmt.Fprintf(&buf, "      <error line=\"%d\" column=\"%d\" message=\"%s (confidence %s)\" severity=\"%s\" source=\"revive/%s\"/>\n",
				is.Line, is.Column, html.EscapeString(is.What), formatFloat(is.Confidence), is.Severity, is.RuleName)
		}
		buf.WriteString("    </file>\n")
	}
	buf.WriteString("</checkstyle>")
	return buf.String(), nil
}
