		fName = color.YellowString(fURL)
	}
	return stylishRow{cells: [3]string{pos, fName, fString}}
}

var ansiRE = regexp.MustCompile("\x1b\\[[0-9;]*m")

func displayWidth(s string) int {
	return utf8.RuneCountInString(ansiRE.ReplaceAllString(s, ""))
}

// Format formats the failures gotten from the lint.
func (*Stylish) Format(failures <-chan lint.Failure, config lint.Config) (string, error) {
	rows := map[string][]stylishRow{}
	var files []string
	totalErrors := 0
	total := 0

	for failure := range failures {
		sev := severity(config, failure)
		total++
		if sev == lint.SeverityError {
			totalErrors++
		}
		fn := failure.GetFilename()
		if _, ok := rows[fn]; !ok {
			files = append(files, fn)
		}
		rows[fn] = append(rows[fn], formatStylishFailure(failure, sev))
	}
