	var buf bytes.Buffer
	for _, fn := range files {
		buf.WriteString(color.New(color.Underline).Sprintf("%s\n", fn))
		buf.WriteString(renderTable(rows[fn]))
		buf.WriteString("\n")
	}

	suffix := fmt.Sprintf(" %d problems (%d errors) (%d warnings)", total, totalErrors, total-totalErrors)
	if total == 1 {
		suffix = fmt.Sprintf(" %d problem (%d errors) (%d warnings)", total, totalErrors, total-totalErrors)
		if totalErrors == 1 {
			suffix = fmt.Sprintf(" %d problem (%d error) (%d warnings)", total, totalErrors, total-totalErrors)
		} else {
			suffix = fmt.Sprintf(" %d problem (%d errors) (%d warning)", total, totalErrors, total-totalErrors)
		}
