		}
		if total-totalErrors == 1 {
			suffix = fmt.Sprintf(" %d problems (%d errors) (%d warning)", total, totalErrors, total-totalErrors)
		}
		if totalErrors == 1 && total-totalErrors == 1 {
			suffix = fmt.Sprintf(" %d problems (%d error) (%d warning)", total, totalErrors, total-totalErrors)
		}
	}

	if total > 0 && totalErrors > 0 {
		suffix = color.RedString("\n ✖" + suffix)
	}
	if total > 0 && totalErrors == 0 {
		suffix = color.YellowString("\n ✖" + suffix)
	}
	if total == 0 {
		return "", nil
	}
	buf.WriteString(suffix)
	return buf.String(), nil
}

func renderTable(rows []stylishRow) string {
	widths := [3]int{}
	for _, r := range rows {
		for i, c := range r.cells {
			if w := displayWidth(c); w > widths[i] {
				widths[i] = w
			}
		}
	}
