package formatter

import (
	"encoding/json"
	"fmt"
	"strings"

	"revive/lint"
)

// Sarif is a formatter producing SARIF output.
type Sarif struct {
	Metadata lint.FormatterMetadata
}

// Name returns the name of the formatter.
func (*Sarif) Name() string {
	return "sarif"
}

const (
	reviveSite = "https://revive.run"
	reviveName = "revive"
)

type sarifObject = map[string]any

// Format formats the failures gotten from the lint.
func (*Sarif) Format(failures <-chan lint.Failure, cfg lint.Config) (string, error) {
	var rules []sarifObject
	for name, ruleCfg := range cfg.Rules {
		props := sarifObject{"severity": string(ruleCfg.Severity)}
		if len(ruleCfg.Arguments) > 0 {
			args := make([]string, 0, len(ruleCfg.Arguments))
			for _, a := range ruleCfg.Arguments {
				args = append(args, fmt.Sprint(a))
			}
			props["arguments"] = strings.Join(args, ",")
		}
		rule := sarifObject{
			"id":         name,
			"helpUri":    ruleDescriptionURL(name),
			"properties": props,
		}
		// the original tool only keeps a single (arbitrary) rule descriptor
		rules = []sarifObject{rule}
	}

	driver := sarifObject{
		"name":           reviveName,
		"informationUri": reviveSite,
	}
	if rules != nil {
		driver["rules"] = rules
	}
	run := sarifObject{
		"tool": sarifObject{"driver": driver},
	}

	var results []sarifObject
	for failure := range failures {
		region := sarifObject{"startLine": failure.Position.Start.Line}
		if failure.Position.Start.Column != 0 {
			region["startColumn"] = failure.Position.Start.Column
		}
		result := sarifObject{
			"ruleId":  failure.RuleName,
			"message": sarifObject{"text": failure.Failure},
			"locations": []sarifObject{{
				"physicalLocation": sarifObject{
					"artifactLocation": sarifObject{"uri": failure.GetFilename()},
					"region":           region,
				},
			}},
		}
		if sev := cfg.Rules[failure.RuleName].Severity; sev != "" {
			result["level"] = string(sev)
		}
		results = append(results, result)
	}
	if results != nil {
		run["results"] = results
	}

	log := sarifObject{
		"version": "2.1.0",
		"runs":    []sarifObject{run},
	}
	out, err := json.MarshalIndent(log, "", "  ")
	if err != nil {
		return "", err
	}
	return string(out), nil
}
