	var maxOpenFiles int
	var setExitStatus, showVersion bool
	fs.StringVar(&configPath, "config", "", "path to the configuration TOML file, defaults to $XDG_CONFIG_HOME/revive.toml or $HOME/revive.toml, if present (i.e. -config myconf.toml)")
	fs.Var(&excludePatterns, "exclude", "list of globs which specify files to be excluded (i.e. -exclude foo/...)")
	fs.StringVar(&formatterName, "formatter", "", "formatter to be used for the output (i.e. -formatter stylish)")
	fs.IntVar(&maxOpenFiles, "max_open_files", 0, "maximum number of open files at the same time")
	fs.BoolVar(&setExitStatus, "set_exit_status", false, "set exit status to 1 if any issues are found, overwrites errorCode and warningCode in config")
	fs.BoolVar(&showVersion, "version", false, "get revive version")
	fs.Usage = func() {
		fmt.Println(banner)
		fs.PrintDefaults()
	}
	_ = fs.Parse(args)

	if showVersion {
		fmt.Printf("Version:\t%s\nCommit:\t\t%s\nBuilt\t\t%s by %s\n", version, commit, date, builtBy)
		return 0
	}

	if configPath == "" {
		configPath = config.DefaultConfigPath()
	}

	conf, err := config.GetConfig(configPath)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}

	if setExitStatus {
		conf.ErrorCode = 1
		conf.WarningCode = 1
	}

	lintingRules, err := config.GetLintingRules(conf, nil)
	if err != nil {
		fmt.Fprintf(os.Stderr, "initializing revive - getting lint rules: %v\n", err)
		return 1
	}

	formatter, err := config.GetFormatter(formatterName)
	if err != nil {
		fmt.Fprintf(os.Stderr, "formatting - getting formatter: %v\n", err)
		return 1
	}

	excludePaths := []string(excludePatterns)
	if len(excludePaths) == 0 {
		excludePaths = conf.Exclude
	}
	if len(excludePaths) == 0 {
		excludePaths = []string{"vendor/..."}
	}

