		if err != nil {
			fmt.Fprintf(os.Stderr, "formatting: %v\n", err)
			os.Exit(1)
		}
		exitChan <- true
	}()

	exitCode := 0
	for f := range failures {
		if f.Confidence < conf.Confidence {
			continue
		}
		if exitCode == 0 {
			exitCode = conf.WarningCode
		}
		if c, ok := conf.Rules[f.RuleName]; ok && c.Severity == lint.SeverityError {
			exitCode = conf.ErrorCode
		}
		if c, ok := conf.Directives[f.RuleName]; ok && c.Severity == lint.SeverityError {
			exitCode = conf.ErrorCode
		}
		f.Severity = lint.SeverityWarning
		if sev := failureSeverity(conf, f); sev == lint.SeverityError {
			f.Severity = lint.SeverityError
		}
		formatChan <- f
	}

	close(formatChan)
	<-exitChan
	if output != "" {
		fmt.Println(output)
	}

	return exitCode
}

func failureSeverity(conf *lint.Config, f lint.Failure) lint.Severity {
	if c, ok := conf.Rules[f.RuleName]; ok && c.Severity == lint.SeverityError {
		return lint.SeverityError
	}
	if c, ok := conf.Directives[f.RuleName]; ok && c.Severity == lint.SeverityError {
		return lint.SeverityError
	}
	return lint.SeverityWarning
}
