package rule

import (
	"fmt"
	"go/ast"
	"go/token"
	"strings"
	"sync"
	"unicode"

	"revive/lint"
)

// commonInitialisms lists common initialisms and their canonical spelling.
var defaultInitialisms = map[string]string{
	"ACL":   "ACL",
	"API":   "API",
	"ASCII": "ASCII",
	"CPU":   "CPU",
	"CSS":   "CSS",
	"DNS":   "DNS",
	"EOF":   "EOF",
	"GUID":  "GUID",
	"HTML":  "HTML",
	"HTTP":  "HTTP",
	"HTTPS": "HTTPS",
	"ID":    "ID",
	"IDS":   "IDs",
	"IP":    "IP",
	"JSON":  "JSON",
	"LHS":   "LHS",
	"QPS":   "QPS",
	"RAM":   "RAM",
	"RHS":   "RHS",
	"RPC":   "RPC",
	"SLA":   "SLA",
	"SMTP":  "SMTP",
	"SQL":   "SQL",
	"SSH":   "SSH",
	"TCP":   "TCP",
	"TLS":   "TLS",
	"TTL":   "TTL",
	"UDP":   "UDP",
	"UI":    "UI",
	"UID":   "UID",
	"UUID":  "UUID",
	"URI":   "URI",
	"URL":   "URL",
	"UTF8":  "UTF8",
	"VM":    "VM",
	"XML":   "XML",
	"XMPP":  "XMPP",
	"XSRF":  "XSRF",
	"XSS":   "XSS",
}

var meaninglessPackageNames = map[string]bool{
	"util":          true,
	"utils":         true,
	"utilities":     true,
	"common":        true,
	"misc":          true,
	"miscellaneous": true,
	"api":           true,
	"types":         true,
	"shared":        true,
	"interfaces":    true,
}

var stdPackageNames = map[string]bool{}

func init() {
	for _, n := range strings.Fields(`adler32 aes ascii85 asn1 ast atomic base32 base64 big binary bits bufio build buildinfo
	bytes bzip2 cgi cgo cipher cmp cmplx color comment constant constraint context cookiejar coverage crc32 crc64 crypto csv
	debug des doc draw driver dsa dwarf ecdh ecdsa ed25519 elf elliptic embed encoding errors exec expvar fcgi filepath flag
	flate fmt fnv format fs fstest gif gob gosym gzip hash heap hex hmac html http httptest httptrace httputil image importer
	io iotest ioutil jpeg json jsonrpc list log lzw macho mail maphash maps math md5 metrics mime multipart net netip os
	palette parse parser path pe pem pkix plan9obj plugin png pprof printer quick quotedprintable race rand rc4 reflect regexp
	ring rpc rsa runtime scanner sha1 sha256 sha512 signal slices slog slogtest smtp sort sql strconv strings subtle suffixarray
	sync syntax syscall syslog tabwriter tar template testing textproto time tls token trace types tzdata unicode unsafe url
	user utf16 utf8 x509 xml zip zlib`) {
		stdPackageNames[n] = true
	}
}

// VarNamingRule lints the naming of variables, types, functions, etc.
type VarNamingRule struct {
	allowList             []string
	blockList             []string
	allowUpperCaseConst   bool
	skipPackageNameChecks bool
	extraBadPackageNames  map[string]bool

	configureOnce sync.Once
	configured    bool
}

// Name returns the rule name.
func (*VarNamingRule) Name() string {
	return "var-naming"
}

// Configure validates the rule configuration, and configures the rule accordingly.
func (r *VarNamingRule) Configure(arguments lint.Arguments) error {
	if len(arguments) >= 1 {
		list, err := getList(arguments[0], "allowlist")
		if err != nil {
			return err
		}
		r.allowList = list
	}

	if len(arguments) >= 2 {
		list, err := getList(arguments[1], "blocklist")
		if err != nil {
			return err
		}
		r.blockList = list
	}

	if len(arguments) >= 3 {
		// not pretty code because should keep compatibility with TOML (no mixed array types) and new map parameters
		thirdArgument := arguments[2]
		asSlice, ok := thirdArgument.([]any)
		if !ok {
			return fmt.Errorf("invalid third argument to the var-naming rule. Expecting a %s of type slice, got %T", "options", arguments[2])
		}
		if len(asSlice) != 1 {
			return fmt.Errorf("invalid third argument to the var-naming rule. Expecting a %s of type slice, of len==1, but %d", "options", len(asSlice))
		}
		args, ok := asSlice[0].(map[string]any)
		if !ok {
			return fmt.Errorf("invalid third argument to the var-naming rule. Expecting a %s of type slice, of len==1, with map, but %T", "options", asSlice[0])
		}
		for k, v := range args {
			switch {
			case isRuleOption(k, "upperCaseConst"):
				r.allowUpperCaseConst = fmt.Sprint(v) == "true"
			case isRuleOption(k, "skipPackageNameChecks"):
				r.skipPackageNameChecks = fmt.Sprint(v) == "true"
			case isRuleOption(k, "extraBadPackageNames"):
				extraBadPackageNames, ok := v.([]any)
				if !ok {
					return fmt.Errorf("invalid third argument to the var-naming rule. Expecting extraBadPackageNames of type slice of strings, but %T", v)
				}
				r.extraBadPackageNames = map[string]bool{}
				for i, name := range extraBadPackageNames {
					s, ok := name.(string)
					if !ok {
						return fmt.Errorf("invalid third argument to the var-naming rule: expected element %d of extraBadPackageNames to be a string, but got %v(%T)", i, name, name)
					}
					r.extraBadPackageNames[strings.ToLower(s)] = true
				}
			}
		}
	}
	r.configured = true
	return nil
}

func (r *VarNamingRule) applyPackageCheckRules(walker *lintNames) {
	// Package names need slightly different handling than other names.
	if r.skipPackageNameChecks {
		return
	}
	pkgNameLower := strings.ToLower(walker.fileAst.Name.Name)
	if r.extraBadPackageNames[pkgNameLower] {
		walker.onFailure(r.packageNameFailure(walker.fileAst.Name, "avoid bad package names"))
		return
	}
	if meaninglessPackageNames[pkgNameLower] {
		walker.onFailure(r.packageNameFailure(walker.fileAst.Name, "avoid meaningless package names"))
		return
	}
	if stdPackageNames[pkgNameLower] {
		walker.onFailure(r.packageNameFailure(walker.fileAst.Name, "avoid package names that conflict with Go standard library package names"))
	}
