	if anyCapsRE.MatchString(walker.fileAst.Name.Name) {
		walker.onFailure(r.packageNameFailure(walker.fileAst.Name, fmt.Sprintf("don't use MixedCaps in package names; %s should be %s", walker.fileAst.Name.Name, pkgNameLower)))
	}
