			copy(runes[i+1:], runes[i+n+1:])
			runes = runes[:len(runes)-n]
		case unicode.IsLower(runes[i]) && !unicode.IsLower(runes[i+1]):
			// lower->non-lower
			eow = true
		}
		i++
		if !eow {
			continue
		}

		// [w,i) is a word.
		word := string(runes[w:i])
		ignoreInitWarnings := map[string]bool{}
		for _, i := range allowList {
			ignoreInitWarnings[i] = true
		}

		extraInits := map[string]bool{}
		for _, i := range blockList {
			extraInits[i] = true
		}

		if u := strings.ToUpper(word); (defaultInitialisms[u] != "" || extraInits[u]) && !ignoreInitWarnings[u] {
			// Keep consistent case, which is lowercase only at the start.
			canonical := defaultInitialisms[u]
			if canonical == "" {
				canonical = u
			}
			if w == 0 && unicode.IsLower(runes[w]) {
				canonical = strings.ToLower(canonical)
			}
			// All the common initialisms are ASCII,
			// so we can replace the bytes exactly.
			copy(runes[w:], []rune(canonical))
		} else if w > 0 && strings.ToLower(word) == word {
			// already all lowercase, and not the first word, so uppercase the first character.
			runes[w] = unicode.ToUpper(runes[w])
		}
		w = i
	}
	return string(runes)
}

func getList(arg any, argName string) ([]string, error) {
	args, ok := arg.([]any)
	if !ok {
		return nil, fmt.Errorf("invalid argument to the var-naming rule. Expecting a %s of type slice with initialisms, got %T", argName, arg)
	}
	var list []string
	for _, v := range args {
		val, ok := v.(string)
		if !ok {
			return nil, fmt.Errorf("invalid %v values of the var-naming rule. Expecting slice of strings but got element of type %T", val, arg)
		}
		list = append(list, val)
	}
	return list, nil
}
