// receiverTypeName returns the name of the receiver type of a method,
// dropping pointer and type parameter decorations.
func receiverTypeName(fn *ast.FuncDecl) string {
	if fn.Recv == nil || len(fn.Recv.List) == 0 {
		return ""
	}
	return typeNameOf(fn.Recv.List[0].Type)
}

func typeNameOf(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.StarExpr:
		return typeNameOf(t.X)
	case *ast.IndexExpr:
		return typeNameOf(t.X)
	case *ast.IndexListExpr:
		return typeNameOf(t.X)
	case *ast.SelectorExpr:
		return typeNameOf(t.Sel)
	}
	return "invalid-type"
}
