// ifElseChainRule is the shared logic of rules looking at if/else constructs
// whose if branch ends with a branching statement.
type ifElseChainRule struct {
	preserveScope bool
}

func (r *ifElseChainRule) configure(arguments lint.Arguments) {
	r.preserveScope = false
	for _, arg := range arguments {
		if s, ok := arg.(string); ok && isRuleOption(s, "preserveScope") {
			r.preserveScope = true
		}
	}
}

// branchKind describes how a block of statements ends.
type branchKind int

const (
	branchEmpty branchKind = iota
	branchReturn
	branchBreak
	branchContinue
	branchGoto
	branchPanic
	branchExit
	branchRegular
)

type blockEnding struct {
	kind     branchKind
	callName string // for panic/exit kinds
}

func (e blockEnding) description() string {
	switch e.kind {
	case branchReturn:
		return "a return statement"
	case branchBreak:
		return "a break statement"
	case branchContinue:
		return "a continue statement"
	case branchGoto:
		return "a goto statement"
	case branchPanic, branchExit:
		return "call to " + e.callName + " function"
	}
	return ""
}

func endingOf(block *ast.BlockStmt) blockEnding {
	if len(block.List) == 0 {
		return blockEnding{kind: branchEmpty}
	}
	switch s := block.List[len(block.List)-1].(type) {
	case *ast.ReturnStmt:
		return blockEnding{kind: branchReturn}
	case *ast.BranchStmt:
		switch s.Tok {
		case token.BREAK:
			return blockEnding{kind: branchBreak}
		case token.CONTINUE:
			return blockEnding{kind: branchContinue}
		case token.GOTO:
			return blockEnding{kind: branchGoto}
		}
	case *ast.ExprStmt:
		if call, ok := s.X.(*ast.CallExpr); ok {
			switch fn := call.Fun.(type) {
			case *ast.Ident:
				if fn.Name == "panic" {
					return blockEnding{kind: branchPanic, callName: "panic"}
				}
			case *ast.SelectorExpr:
				if pkg, ok := fn.X.(*ast.Ident); ok && isCallToExitFunction(pkg.Name, fn.Sel.Name) {
					return blockEnding{kind: branchExit, callName: pkg.Name + "." + fn.Sel.Name}
				}
			}
		}
	}
	return blockEnding{kind: branchRegular}
}

// blockDeclaresSymbols reports whether a block directly declares symbols in its scope.
func blockDeclaresSymbols(block *ast.BlockStmt) bool {
	for _, stmt := range block.List {
		switch s := stmt.(type) {
		case *ast.DeclStmt:
			return true
		case *ast.AssignStmt:
			if s.Tok == token.DEFINE {
				return true
			}
		}
	}
	return false
}

type ifElseVisitor struct {
	rule      *ifElseChainRule
	onFailure func(lint.Failure)
	accept    func(blockEnding) bool
}

func (v *ifElseVisitor) Visit(node ast.Node) ast.Visitor {
	ifStmt, ok := node.(*ast.IfStmt)
	if !ok || ifStmt.Else == nil {
		return v
	}
	elseBlock, ok := ifStmt.Else.(*ast.BlockStmt)
	if !ok {
		// only care about elses without conditions
		return v
	}
	ending := endingOf(ifStmt.Body)
	if !v.accept(ending) {
		return v
	}

	shortDecl := false // does the if statement have a ":=" initialization statement?
	if ifStmt.Init != nil {
		if as, ok := ifStmt.Init.(*ast.AssignStmt); ok && as.Tok == token.DEFINE {
			shortDecl = true
		}
	}

	if v.rule.preserveScope && (shortDecl || blockDeclaresSymbols(elseBlock)) {
		return v
	}

	extra := ""
	if shortDecl {
		extra = " (move short variable declaration to its own line if necessary)"
	}
	v.onFailure(lint.Failure{
		Confidence: 1,
		Node:       ifStmt.Else,
		Failure:    fmt.Sprintf("if block ends with %s, so drop this else and outdent its block%s", ending.description(), extra),
	})
	return v
}

func (r *ifElseChainRule) apply(file *lint.File, accept func(blockEnding) bool) []lint.Failure {
	var failures []lint.Failure
	v := &ifElseVisitor{
		rule:   r,
		accept: accept,
		onFailure: func(f lint.Failure) {
			failures = append(failures, f)
		},
	}
	ast.Walk(v, file.AST)
	return failures
}
