	return nil
}

// Apply applies the rule to given file.
func (r *CognitiveComplexityRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure

	for _, decl := range file.AST.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}
		v := &cognitiveComplexityVisitor{name: fn.Name}
		ast.Walk(v, fn.Body)
		if v.complexity > r.maxComplexity {
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Category:   "maintenance",
				Failure:    fmt.Sprintf("function %s has cognitive complexity %d (> max enabled %d)", funcName(fn), v.complexity, r.maxComplexity),
				Node:       fn,
			})
		}
	}

	return failures
}

type cognitiveComplexityVisitor struct {
	name         *ast.Ident
	complexity   int
	nesting      int
	elseNodes    map[ast.Node]bool
	calculated   map[ast.Expr]bool
}

func (v *cognitiveComplexityVisitor) incNesting() { v.nesting++ }
func (v *cognitiveComplexityVisitor) decNesting() { v.nesting-- }
func (v *cognitiveComplexityVisitor) incComplexity() { v.complexity++ }
func (v *cognitiveComplexityVisitor) nestIncComplexity() {
	v.complexity += v.nesting + 1
}

func (v *cognitiveComplexityVisitor) markAsElseNode(n ast.Node) {
	if v.elseNodes == nil {
		v.elseNodes = make(map[ast.Node]bool)
	}
	v.elseNodes[n] = true
}

func (v *cognitiveComplexityVisitor) markedAsElseNode(n ast.Node) bool {
	return v.elseNodes[n]
}

func (v *cognitiveComplexityVisitor) markCalculated(e ast.Expr) {
	if v.calculated == nil {
		v.calculated = make(map[ast.Expr]bool)
	}
	v.calculated[e] = true
}

func (v *cognitiveComplexityVisitor) isCalculated(e ast.Expr) bool {
	return v.calculated[e]
}

// Visit implements the ast.Visitor interface.
func (v *cognitiveComplexityVisitor) Visit(n ast.Node) ast.Visitor {
	switch n := n.(type) {
	case *ast.IfStmt:
		return v.visitIfStmt(n)
	case *ast.SwitchStmt:
		return v.visitSwitchStmt(n)
	case *ast.TypeSwitchStmt:
		return v.visitTypeSwitchStmt(n)
	case *ast.SelectStmt:
		return v.visitSelectStmt(n)
	case *ast.ForStmt:
		return v.visitForStmt(n)
	case *ast.RangeStmt:
		return v.visitRangeStmt(n)
	case *ast.FuncLit:
		return v.visitFuncLit(n)
	case *ast.BranchStmt:
		return v.visitBranchStmt(n)
	case *ast.BinaryExpr:
		return v.visitBinaryExpr(n)
	case *ast.CallExpr:
		return v.visitCallExpr(n)
	}
	return v
}

func (v *cognitiveComplexityVisitor) visitIfStmt(n *ast.IfStmt) ast.Visitor {
	v.incIfComplexity(n)

	if n := n.Init; n != nil {
		ast.Walk(v, n)
	}

	ast.Walk(v, n.Cond)

	v.incNesting()
	ast.Walk(v, n.Body)
	v.decNesting()

	if _, ok := n.Else.(*ast.BlockStmt); ok {
		v.incComplexity()
		ast.Walk(v, n.Else)
	} else if elseIf, ok := n.Else.(*ast.IfStmt); ok {
		v.markAsElseNode(elseIf)
		ast.Walk(v, n.Else)
	}

	return nil
}

func (v *cognitiveComplexityVisitor) incIfComplexity(n *ast.IfStmt) {
	if v.markedAsElseNode(n) {
		v.incComplexity()
	} else {
		v.nestIncComplexity()
	}
}

func (v *cognitiveComplexityVisitor) visitSwitchStmt(n *ast.SwitchStmt) ast.Visitor {
	v.nestIncComplexity()

	if n := n.Init; n != nil {
		ast.Walk(v, n)
	}

	if n := n.Tag; n != nil {
		ast.Walk(v, n)
	}

	v.incNesting()
	ast.Walk(v, n.Body)
	v.decNesting()

	return nil
}

func (v *cognitiveComplexityVisitor) visitTypeSwitchStmt(n *ast.TypeSwitchStmt) ast.Visitor {
	v.nestIncComplexity()

	if n := n.Init; n != nil {
		ast.Walk(v, n)
	}

	if n := n.Assign; n != nil {
		ast.Walk(v, n)
	}

	v.incNesting()
	ast.Walk(v, n.Body)
	v.decNesting()

	return nil
}

func (v *cognitiveComplexityVisitor) visitSelectStmt(n *ast.SelectStmt) ast.Visitor {
	v.nestIncComplexity()

	v.incNesting()
	ast.Walk(v, n.Body)
	v.decNesting()

	return nil
}

func (v *cognitiveComplexityVisitor) visitForStmt(n *ast.ForStmt) ast.Visitor {
	v.nestIncComplexity()

	if n := n.Init; n != nil {
		ast.Walk(v, n)
	}

	if n := n.Cond; n != nil {
		ast.Walk(v, n)
	}

	if n := n.Post; n != nil {
		ast.Walk(v, n)
	}

	v.incNesting()
	ast.Walk(v, n.Body)
	v.decNesting()

	return nil
}

func (v *cognitiveComplexityVisitor) visitRangeStmt(n *ast.RangeStmt) ast.Visitor {
	v.nestIncComplexity()

	if n := n.Key; n != nil {
		ast.Walk(v, n)
	}

	if n := n.Value; n != nil {
		ast.Walk(v, n)
	}

	ast.Walk(v, n.X)

	v.incNesting()
	ast.Walk(v, n.Body)
	v.decNesting()

	return nil
}

func (v *cognitiveComplexityVisitor) visitFuncLit(n *ast.FuncLit) ast.Visitor {
	ast.Walk(v, n.Type)

	v.incNesting()
	ast.Walk(v, n.Body)
	v.decNesting()

	return nil
}

func (v *cognitiveComplexityVisitor) visitBranchStmt(n *ast.BranchStmt) ast.Visitor {
	if n.Label != nil {
		v.incComplexity()
	}
	return v
}

func (v *cognitiveComplexityVisitor) visitBinaryExpr(n *ast.BinaryExpr) ast.Visitor {
	if isBinaryLogicalOp(n.Op) && !v.isCalculated(n) {
		ops := v.collectBinaryOps(n)

		var lastOp token.Token
		for _, op := range ops {
			if isBinaryLogicalOp(op) && op != lastOp {
				v.incComplexity()
				lastOp = op
			}
		}
	}
	return v
}

func (v *cognitiveComplexityVisitor) visitCallExpr(n *ast.CallExpr) ast.Visitor {
	if name, ok := n.Fun.(*ast.Ident); ok {
		if name.Obj == v.name.Obj && name.Name == v.name.Name {
			v.incComplexity()
		}
	}
	return v
}

func (v *cognitiveComplexityVisitor) collectBinaryOps(exp ast.Expr) []token.Token {
	v.markCalculated(exp)
	if exp, ok := exp.(*ast.BinaryExpr); ok {
		return mergeBinaryOps(v.collectBinaryOps(exp.X), exp.Op, v.collectBinaryOps(exp.Y))
	}
	return []token.Token{}
}

func mergeBinaryOps(x []token.Token, op token.Token, y []token.Token) []token.Token {
	var out []token.Token
	if len(x) != 0 {
		out = append(out, x...)
	}
	out = append(out, op)
	if len(y) != 0 {
		out = append(out, y...)
	}
	return out
}

func isBinaryLogicalOp(op token.Token) bool {
	return op == token.LAND || op == token.LOR
}
