package rule

import (
	"fmt"
	"go/ast"

	"revive/lint"
)

// MaxControlNestingRule sets restriction for maximum nesting of control structures.
type MaxControlNestingRule struct {
	max int64
}

const defaultMaxControlNesting = 5

// Name returns the rule name.
func (*MaxControlNestingRule) Name() string {
	return "max-control-nesting"
}

// Configure validates the rule configuration, and configures the rule accordingly.
func (r *MaxControlNestingRule) Configure(arguments lint.Arguments) error {
	if len(arguments) < 1 {
		r.max = defaultMaxControlNesting
		return nil
	}

	maxNesting, ok := arguments[0].(int64) // Alt. non panicking version
	if !ok {
		return fmt.Errorf(`invalid value passed as argument number to the "max-control-nesting" rule`)
	}
	r.max = maxNesting
	return nil
}

// Apply applies the rule to given file.
func (r *MaxControlNestingRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure

	fileAst := file.AST

	walker := &lintMaxControlNesting{
		max: r.max,
		onFailure: func(failure lint.Failure) {
			failures = append(failures, failure)
		},
	}

	ast.Walk(walker, fileAst)

	return failures
}

type lintMaxControlNesting struct {
	max          int64
	nestingLevel int64
	onFailure    func(lint.Failure)
}

func (w *lintMaxControlNesting) Visit(n ast.Node) ast.Visitor {
	if w.nestingLevel > w.max {
		w.onFailure(lint.Failure{
			Failure:    fmt.Sprintf("control flow nesting exceeds %d", w.max),
			Confidence: 1,
			Node:       w.lastCtrlStmt,
			Category:   "complexity",
		})
		return nil // stop visiting deeper
	}

	switch v := n.(type) {
	case *ast.IfStmt:
		w.walkControlledBlock(v, v.Body)
		if v.Else != nil {
			w.walkControlledBlock(v, v.Else)
		}
		return nil
	case *ast.ForStmt:
		w.walkControlledBlock(v, v.Body)
		return nil
	case *ast.RangeStmt:
		w.walkControlledBlock(v, v.Body)
		return nil
	case *ast.SwitchStmt:
		w.walkControlledBlock(v, v.Body)
		return nil
	case *ast.TypeSwitchStmt:
		w.walkControlledBlock(v, v.Body)
		return nil
	case *ast.SelectStmt:
		w.walkControlledBlock(v, v.Body)
		return nil
	}

	return w
}

func (w *lintMaxControlNesting) walkControlledBlock(ctrl ast.Node, b ast.Node) {
	oldNestingLevel := w.nestingLevel
	oldLastCtrl := w.lastCtrlStmt
	w.lastCtrlStmt = ctrl
	w.nestingLevel++
	ast.Walk(w, b)
	w.nestingLevel = oldNestingLevel
	w.lastCtrlStmt = oldLastCtrl
}
