package rule

import (
	"fmt"
	"go/ast"
	"strings"
	"unicode"
	"unicode/utf8"

	"revive/lint"
)

// DeepExitRule lints program exit at functions other than main or init.
type DeepExitRule struct{}

// Name returns the rule name.
func (*DeepExitRule) Name() string {
	return "deep-exit"
}

// Apply applies the rule to given file.
func (*DeepExitRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	onFailure := func(failure lint.Failure) {
		failures = append(failures, failure)
	}

	w := &lintDeepExit{
		onFailure:  onFailure,
		isTestFile: file.IsTest(),
	}
	ast.Walk(w, file.AST)
	return failures
}

type lintDeepExit struct {
	onFailure  func(lint.Failure)
	isTestFile bool
	exempt     bool
}

func (w *lintDeepExit) Visit(node ast.Node) ast.Visitor {
	switch n := node.(type) {
	case *ast.FuncDecl:
		if n.Body == nil {
			return nil
		}
		nw := &lintDeepExit{onFailure: w.onFailure, isTestFile: w.isTestFile, exempt: w.mustIgnore(n)}
		ast.Walk(nw, n.Body)
		return nil
	case *ast.FuncLit:
		nw := &lintDeepExit{onFailure: w.onFailure, isTestFile: w.isTestFile, exempt: false}
		ast.Walk(nw, n.Body)
		return nil
	case *ast.ExprStmt:
		if w.exempt {
			return w
		}
		ce, ok := n.X.(*ast.CallExpr)
		if !ok {
			return w
		}
		se, ok := ce.Fun.(*ast.SelectorExpr)
		if !ok {
			return w
		}
		id, ok := se.X.(*ast.Ident)
		if !ok {
			return w
		}
		pkg := id.Name
		fn := se.Sel.Name
		if isCallToExitFunction(pkg, fn) {
			w.onFailure(lint.Failure{
				Confidence: 1,
				Node:       ce,
				Category:   "bad practice",
				Failure:    fmt.Sprintf("calls to %s.%s only in main() or init() functions", pkg, fn),
			})
		}
	}
	return w
}

func (w *lintDeepExit) mustIgnore(fd *ast.FuncDecl) bool {
	fn := fd.Name.Name
	if fn == "init" || fn == "main" {
		return true
	}
	if !w.isTestFile {
		return false
	}
	if fn == "TestMain" {
		return true
	}
	if fd.Recv != nil {
		return false
	}
	return isTestFunction(fd) || isExampleFunction(fd)
}

// isTestFunction reports whether the declaration looks like func TestXxx(t *testing.T).
func isTestFunction(fd *ast.FuncDecl) bool {
	name := fd.Name.Name
	if !strings.HasPrefix(name, "Test") || len(name) == len("Test") {
		return false
	}
	c := name[len("Test")]
	if c < 'A' || c > 'Z' {
		return false
	}
	if fd.Type.Results != nil && len(fd.Type.Results.List) > 0 {
		return false
	}
	params := fd.Type.Params.List
	if len(params) != 1 || len(params[0].Names) > 1 {
		return false
	}
	return gofmt(params[0].Type) == "*testing.T"
}

// isExampleFunction reports whether the declaration looks like func ExampleXxx().
func isExampleFunction(fd *ast.FuncDecl) bool {
	name := fd.Name.Name
	if !strings.HasPrefix(name, "Example") {
		return false
	}
	if len(name) > len("Example") {
		r, _ := utf8.DecodeRuneInString(name[len("Example"):])
		if unicode.IsLower(r) {
			return false
		}
	}
	return fd.Type.Params == nil || len(fd.Type.Params.List) == 0
}
