package rule

import (
	"fmt"
	"go/ast"
	"go/token"

	"revive/lint"
)

// branchKind describes how a block of statements ends.
type branchKind int

const (
	branchEmpty branchKind = iota
	branchReturn
	branchBreak
	branchContinue
	branchGoto
	branchPanic
	branchExit
	branchRegular
)

// deviates reports whether the ending makes the control flow leave the block.
func (k branchKind) deviates() bool {
	switch k {
	case branchReturn, branchBreak, branchContinue, branchGoto, branchPanic, branchExit:
		return true
	}
	return false
}

// String returns the keyword of the deviating statement.
func (k branchKind) String() string {
	switch k {
	case branchReturn:
		return "return"
	case branchBreak:
		return "break"
	case branchContinue:
		return "continue"
	case branchGoto:
		return "goto"
	case branchPanic:
		return "panic"
	case branchExit:
		return "exit"
	}
	return ""
}

// branch describes the end of a block of statements.
type branch struct {
	kind     branchKind
	callName string // for panic/exit kinds
	hasDecls bool   // the block directly declares symbols
	stmts    []ast.Stmt
}

func (b branch) deviates() bool { return b.kind.deviates() }

func (b branch) isEmpty() bool { return b.kind == branchEmpty }

// isShort reports whether the branch is empty or consists of at most two
// simple statements (without nested blocks).
func (b branch) isShort() bool {
	switch len(b.stmts) {
	case 0:
		return true
	case 1:
		return isSimpleStmt(b.stmts[0])
	case 2:
		return isSimpleStmt(b.stmts[0]) && isSimpleStmt(b.stmts[1])
	}
	return false
}

func isSimpleStmt(stmt ast.Stmt) bool {
	switch stmt.(type) {
	case *ast.BlockStmt, *ast.IfStmt, *ast.ForStmt, *ast.RangeStmt, *ast.SwitchStmt, *ast.TypeSwitchStmt, *ast.SelectStmt:
		return false
	}
	return true
}

// longString describes the branch ending, as used in failure messages.
func (b branch) longString() string {
	switch b.kind {
	case branchReturn:
		return "a return statement"
	case branchBreak:
		return "a break statement"
	case branchContinue:
		return "a continue statement"
	case branchGoto:
		return "a goto statement"
	case branchPanic, branchExit:
		return "call to " + b.callName + " function"
	}
	return ""
}

// String describes the branch as it would appear in an else block.
func (b branch) String() string {
	switch b.kind {
	case branchPanic, branchExit:
		return "... " + b.callName + "()"
	case branchReturn, branchBreak, branchContinue, branchGoto:
		return "... " + b.kind.String()
	}
	return "..."
}

func blockBranch(block *ast.BlockStmt) branch {
	if len(block.List) == 0 {
		return branch{kind: branchEmpty}
	}
	b := stmtBranch(block.List[len(block.List)-1])
	b.hasDecls = blockDeclaresSymbols(block)
	b.stmts = block.List
	return b
}

func stmtBranch(stmt ast.Stmt) branch {
	switch s := stmt.(type) {
	case *ast.ReturnStmt:
		return branch{kind: branchReturn}
	case *ast.BlockStmt:
		return blockBranch(s)
	case *ast.LabeledStmt:
		return stmtBranch(s.Stmt)
	case *ast.EmptyStmt:
		return branch{kind: branchEmpty}
	case *ast.BranchStmt:
		switch s.Tok {
		case token.BREAK:
			return branch{kind: branchBreak}
		case token.CONTINUE:
			return branch{kind: branchContinue}
		case token.GOTO:
			return branch{kind: branchGoto}
		}
	case *ast.ExprStmt:
		if call, ok := s.X.(*ast.CallExpr); ok {
			switch fn := call.Fun.(type) {
			case *ast.Ident:
				if fn.Name == "panic" {
					return branch{kind: branchPanic, callName: "panic"}
				}
			case *ast.SelectorExpr:
				if pkg, ok := fn.X.(*ast.Ident); ok && isCallToExitFunction(pkg.Name, fn.Sel.Name) {
					return branch{kind: branchExit, callName: pkg.Name + "." + fn.Sel.Name}
				}
			}
		}
	}
	return branch{kind: branchRegular}
}

// blockDeclaresSymbols reports whether a block directly declares symbols in its scope.
func blockDeclaresSymbols(block *ast.BlockStmt) bool {
	for _, stmt := range block.List {
		switch s := stmt.(type) {
		case *ast.DeclStmt:
			return true
		case *ast.AssignStmt:
			if s.Tok == token.DEFINE {
				return true
			}
		}
	}
	return false
}

// ifChain describes an if statement inside an if/else-if/else chain.
type ifChain struct {
	ifBranch            branch
	hasElse             bool
	elseBranch          branch
	hasInitializer      bool
	hasPriorNonDeviating bool
	atBlockEnd          bool
	blockEndKind        branchKind
}

// ifElseArgs holds the arguments shared by the if/else related rules.
type ifElseArgs struct {
	preserveScope bool
	allowJump     bool
}

func parseIfElseArgs(arguments lint.Arguments) ifElseArgs {
	var args ifElseArgs
	for _, arg := range arguments {
		s, ok := arg.(string)
		if !ok {
			continue
		}
		switch {
		case isRuleOption(s, "preserveScope"):
			args.preserveScope = true
		case isRuleOption(s, "allowJump"):
			args.allowJump = true
		}
	}
	return args
}

// ifElseChecker decides, for a given chain, whether to report a failure.
type ifElseChecker func(chain ifChain, args ifElseArgs) (string, bool)

type ifElseTarget int

const (
	targetIf ifElseTarget = iota
	targetElse
)

type ifElseVisitor struct {
	check     ifElseChecker
	args      ifElseArgs
	target    ifElseTarget
	onFailure func(lint.Failure)
	endKind   branchKind
}

func (v *ifElseVisitor) Visit(node ast.Node) ast.Visitor {
	switch n := node.(type) {
	case *ast.FuncDecl:
		if n.Body != nil {
			v.visitBlock(n.Body.List, branchReturn)
		}
		return nil
	case *ast.FuncLit:
		v.visitBlock(n.Body.List, branchReturn)
		return nil
	case *ast.ForStmt:
		v.visitBlock(n.Body.List, branchContinue)
		return nil
	case *ast.RangeStmt:
		v.visitBlock(n.Body.List, branchContinue)
		return nil
	case *ast.CaseClause:
		v.visitBlock(n.Body, branchBreak)
		return nil
	case *ast.CommClause:
		v.visitBlock(n.Body, branchRegular)
		return nil
	case *ast.BlockStmt:
		v.visitBlock(n.List, branchRegular)
		return nil
	}
	return v
}

func (v *ifElseVisitor) visitBlock(list []ast.Stmt, endKind branchKind) {
	for i, s := range list {
		ifStmt, ok := s.(*ast.IfStmt)
		if !ok {
			ast.Walk(v, s)
			continue
		}
		v.visitChain(ifStmt, ifChain{atBlockEnd: i == len(list)-1, blockEndKind: endKind})
	}
}

func (v *ifElseVisitor) visitChain(ifStmt *ast.IfStmt, chain ifChain) {
	// look for other if-else chains nested inside this if { } block
	if ifStmt.Init != nil {
		ast.Walk(v, ifStmt.Init)
	}
	ast.Walk(v, ifStmt.Cond)
	v.visitBlock(ifStmt.Body.List, branchRegular)

	if as, ok := ifStmt.Init.(*ast.AssignStmt); ok && as.Tok == token.DEFINE {
		chain.hasInitializer = true
	}
	chain.ifBranch = blockBranch(ifStmt.Body)

	switch elseBlock := ifStmt.Else.(type) {
	case *ast.IfStmt:
		if !chain.ifBranch.deviates() {
			chain.hasPriorNonDeviating = true
		}
		v.visitChain(elseBlock, chain)
		return
	case *ast.BlockStmt:
		// look for other if-else chains nested inside this else { } block
		v.visitBlock(elseBlock.List, branchRegular)
		chain.hasElse = true
		chain.elseBranch = blockBranch(elseBlock)
	case nil:
		chain.hasElse = false
	default:
		return
	}

	msg, ok := v.check(chain, v.args)
	if !ok {
		return
	}
	if chain.hasInitializer {
		// if statement has a := initializer, so we might need to move the assignment
		// onto its own line in case the body references it
		msg += " (move short variable declaration to its own line if necessary)"
	}
	var node ast.Node = ifStmt
	if v.target == targetElse {
		node = ifStmt.Else
	}
	v.onFailure(lint.Failure{
		Confidence: 1,
		Node:       node,
		Failure:    msg,
	})
}

func applyIfElseRule(file *lint.File, check ifElseChecker, args ifElseArgs, target ifElseTarget) []lint.Failure {
	var failures []lint.Failure
	v := &ifElseVisitor{
		check:  check,
		args:   args,
		target: target,
		onFailure: func(f lint.Failure) {
			failures = append(failures, f)
		},
	}
	ast.Walk(v, file.AST)
	return failures
}

// checkIndentErrorFlow is the checker of the indent-error-flow rule.
func checkIndentErrorFlow(chain ifChain, args ifElseArgs) (string, bool) {
	if !chain.hasElse || chain.ifBranch.kind != branchReturn {
		return "", false
	}
	if chain.hasPriorNonDeviating {
		return "", false
	}
	if args.preserveScope && !chain.atBlockEnd && (chain.hasInitializer || chain.elseBranch.hasDecls) {
		return "", false
	}
	return fmt.Sprintf("if block ends with %v, so drop this else and outdent its block", chain.ifBranch.longString()), true
}

// checkSuperfluousElse is the checker of the superfluous-else rule.
func checkSuperfluousElse(chain ifChain, args ifElseArgs) (string, bool) {
	if !chain.hasElse {
		return "", false
	}
	switch chain.ifBranch.kind {
	case branchBreak, branchContinue, branchGoto, branchPanic, branchExit:
	default:
		return "", false
	}
	if chain.hasPriorNonDeviating {
		return "", false
	}
	if args.preserveScope && !chain.atBlockEnd && (chain.hasInitializer || chain.elseBranch.hasDecls) {
		return "", false
	}
	return fmt.Sprintf("if block ends with %v, so drop this else and outdent its block", chain.ifBranch.longString()), true
}

// checkEarlyReturn is the checker of the early-return rule.
func checkEarlyReturn(chain ifChain, args ifElseArgs) (string, bool) {
	if chain.hasElse {
		if !chain.elseBranch.deviates() {
			// this rule only applies if the else-block deviates control flow
			return "", false
		}
	} else if !args.allowJump || !chain.atBlockEnd || !chain.blockEndKind.deviates() || chain.ifBranch.isShort() {
		// this kind of refactor requires introducing a new indented "return", "continue" or "break" statement,
		// so ignore unless we are able to outdent multiple statements in exchange.
		return "", false
	}

	if chain.hasPriorNonDeviating && !chain.ifBranch.isEmpty() {
		// if we de-indent this block then a previous branch
		// might flow into it, affecting program behavior
		return "", false
	}

	if chain.hasElse && chain.ifBranch.deviates() {
		// avoid overlapping with superfluous-else
		return "", false
	}

	if args.preserveScope && !chain.atBlockEnd && (chain.hasInitializer || chain.ifBranch.hasDecls) {
		// avoid increasing variable scope
		return "", false
	}

	if !chain.hasElse {
		return fmt.Sprintf("if c { ... } can be rewritten if !c { %v } ... to reduce nesting", chain.blockEndKind), true
	}

	if chain.ifBranch.isEmpty() {
		return fmt.Sprintf("if c { } else { %[1]v } can be simplified to if !c { %[1]v }", chain.elseBranch), true
	}
	return fmt.Sprintf("if c { ... } else { %[1]v } can be simplified to if !c { %[1]v } ...", chain.elseBranch), true
}
