package rule

import (
	"bytes"
	"go/ast"
	"go/token"

	"revive/lint"
)

// EmptyLinesRule lints empty lines in blocks.
type EmptyLinesRule struct{}

// Name returns the rule name.
func (*EmptyLinesRule) Name() string {
	return "empty-lines"
}

// Apply applies the rule to given file.
func (*EmptyLinesRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure

	onFailure := func(failure lint.Failure) {
		failures = append(failures, failure)
	}

	w := lintEmptyLines{file, bytes.Split(file.Content(), []byte("\n")), onFailure}
	ast.Walk(w, file.AST)
	return failures
}

type lintEmptyLines struct {
	file      *lint.File
	lines     [][]byte
	onFailure func(lint.Failure)
}

func (w lintEmptyLines) Visit(node ast.Node) ast.Visitor {
	block, ok := node.(*ast.BlockStmt)
	if !ok {
		return w
	}

	w.checkStart(block)
	w.checkEnd(block)

	return w
}

func (w lintEmptyLines) checkStart(block *ast.BlockStmt) {
	if len(block.List) == 0 {
		return
	}

	start := w.position(block.Lbrace)
	first := w.position(block.List[0].Pos())
	if first.Line-start.Line > 1 && w.isBlankLine(start.Line+1) {
		w.onFailure(lint.Failure{
			Confidence: 1,
			Node:       block,
			Category:   "style",
			Failure:    "extra empty line at the start of a block",
		})
	}
}

func (w lintEmptyLines) checkEnd(block *ast.BlockStmt) {
	if len(block.List) < 1 {
		return
	}

	end := w.position(block.Rbrace)
	last := w.position(block.List[len(block.List)-1].End())
	if end.Line-last.Line > 1 && w.isBlankLine(end.Line-1) {
		w.onFailure(lint.Failure{
			Confidence: 1,
			Node:       block,
			Category:   "style",
			Failure:    "extra empty line at the end of a block",
		})
	}
}

// isBlankLine reports whether the given (1-based) line contains only white space.
func (w lintEmptyLines) isBlankLine(line int) bool {
	if line < 1 || line > len(w.lines) {
		return false
	}
	return len(bytes.TrimSpace(w.lines[line-1])) == 0
}

func (w lintEmptyLines) position(pos token.Pos) token.Position {
	return w.file.ToPosition(pos)
}
