package rule

import (
	"fmt"
	"go/ast"

	"revive/lint"
)

// FlagParamRule warns on boolean parameters that create a control coupling.
type FlagParamRule struct{}

// Name returns the rule name.
func (*FlagParamRule) Name() string {
	return "flag-parameter"
}

// Apply applies the rule to given file.
func (*FlagParamRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure

	onFailure := func(failure lint.Failure) {
		failures = append(failures, failure)
	}

	w := lintFlagParamRule{onFailure: onFailure}
	ast.Walk(w, file.AST)
	return failures
}

type lintFlagParamRule struct {
	onFailure func(lint.Failure)
}

func (w lintFlagParamRule) Visit(node ast.Node) ast.Visitor {
	var funcType *ast.FuncType
	var body *ast.BlockStmt
	switch n := node.(type) {
	case *ast.FuncDecl:
		funcType, body = n.Type, n.Body
	case *ast.FuncLit:
		funcType, body = n.Type, n.Body
	default:
		return w
	}

	if body == nil {
		return w // skip, is a function prototype
	}

	// Scan params for boolean params
	boolParams := map[string]struct{}{}
	for _, param := range funcType.Params.List {
		if !isIdent(param.Type, "bool") {
			continue
		}

		for _, paramIdent := range param.Names {
			boolParams[paramIdent.Name] = struct{}{}
		}
	}

	if len(boolParams) == 0 {
		return w // skip, func without bool params
	}

	cv := conditionVisitor{boolParams, funcType.Params, w.onFailure}
	ast.Walk(cv, body)

	return w
}

type conditionVisitor struct {
	idents    map[string]struct{}
	params    *ast.FieldList
	onFailure func(lint.Failure)
}

func (w conditionVisitor) Visit(node ast.Node) ast.Visitor {
	var conds []ast.Expr
	switch n := node.(type) {
	case *ast.FuncLit:
		return nil // do not analyse nested function literals
	case *ast.IfStmt:
		conds = []ast.Expr{n.Cond}
	case *ast.CaseClause:
		conds = n.List
	default:
		return w
	}

	fselect := func(n ast.Node) bool {
		ident, ok := n.(*ast.Ident)
		if !ok {
			return false
		}
		_, ok = w.idents[ident.Name]
		return ok
	}

	for _, cond := range conds {
		uses := pick(cond, fselect)
		if len(uses) < 1 {
			continue
		}
		ident := uses[0].(*ast.Ident)
		w.onFailure(lint.Failure{
			Confidence: 1,
			Node:       w.params,
			Category:   "bad practice",
			Failure:    fmt.Sprintf("parameter '%s' seems to be a control flag, avoid control coupling", ident.Name),
		})
		return nil
	}

	return w
}
