// GoVersion returns the Go language version declared in the go.mod file governing
// the package directory (e.g. "go1.21"). It returns an empty string if the version
// cannot be determined.
func (p *Package) GoVersion() string {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.goVersionLoaded {
		return p.goVersion
	}
	p.goVersionLoaded = true
	for name := range p.files {
		p.goVersion = goVersionFor(filepath.Dir(name))
		break
	}
	return p.goVersion
}

var (
	goModCache   = map[string]string{}
	goModCacheMu sync.Mutex
)

// goVersionFor looks up the go directive of the closest go.mod file.
func goVersionFor(dir string) string {
	abs, err := filepath.Abs(dir)
	if err != nil {
		return ""
	}
	goModCacheMu.Lock()
	defer goModCacheMu.Unlock()
	if v, ok := goModCache[abs]; ok {
		return v
	}
	v := ""
	for d := abs; ; {
		data, err := os.ReadFile(filepath.Join(d, "go.mod"))
		if err == nil {
			v = parseGoDirective(data)
			break
		}
		parent := filepath.Dir(d)
		if parent == d {
			break
		}
		d = parent
	}
	goModCache[abs] = v
	return v
}

func parseGoDirective(data []byte) string {
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if i := strings.Index(line, "//"); i >= 0 {
			line = strings.TrimSpace(line[:i])
		}
		fields := strings.Fields(line)
		if len(fields) == 2 && fields[0] == "go" {
			return "go" + fields[1]
		}
	}
	return ""
}

// IsAtLeastGoVersion reports whether the package's Go version is at least the given one (e.g. "go1.24").
func (p *Package) IsAtLeastGoVersion(v string) bool {
	return version.Compare(p.GoVersion(), v) >= 0
}
