actions.command:
cd /workspace && cat > rule/struct_tag.go <<'EOF'
package rule

import (
	"fmt"
	"go/ast"
	"strconv"
	"strings"

	"revive/lint"
)

// StructTagRule lints struct tags.
type StructTagRule struct {
	userDefined map[string][]string // map: key -> []option
}

// Name returns the rule name.
func (*StructTagRule) Name() string {
	return "struct-tag"
}

// Configure validates the rule configuration, and configures the rule accordingly.
func (r *StructTagRule) Configure(arguments lint.Arguments) error {
	if len(arguments) == 0 {
		return nil
	}

	err := checkNumberOfArguments(1, arguments, r.Name())
	if err != nil {
		return err
	}
	r.userDefined = make(map[string][]string, len(arguments))
	for _, arg := range arguments {
		item, ok := arg.(string)
		if !ok {
			return fmt.Errorf("invalid argument to the %s rule. Expecting a string, got %v (of type %T)", r.Name(), arg, arg)
		}
		parts := strings.Split(item, ",")
		if len(parts) < 2 {
			return fmt.Errorf("invalid argument to the %s rule. Expecting a string of the form key[,option]+, got %s", r.Name(), item)
		}
		key := strings.TrimSpace(parts[0])
		for i := 1; i < len(parts); i++ {
			option := strings.TrimSpace(parts[i])
			r.userDefined[key] = append(r.userDefined[key], option)
		}
	}
	return nil
}

// Apply applies the rule to given file.
func (r *StructTagRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	onFailure := func(failure lint.Failure) {
		failures = append(failures, failure)
	}

	w := lintStructTagRule{
		onFailure:      onFailure,
		userDefined:    r.userDefined,
		isAtLeastGo124: file.Pkg.IsAtLeastGoVersion("go1.24"),
	}

	ast.Walk(w, file.AST)

	return failures
}

type lintStructTagRule struct {
	onFailure      func(lint.Failure)
	userDefined    map[string][]string // map: key -> []option
	usedTagNbr     map[int]bool        // list of used tag numbers
	usedTagName    map[string]bool     // list of used tag keys
	isAtLeastGo124 bool
}

func (w lintStructTagRule) Visit(node ast.Node) ast.Visitor {
	switch n := node.(type) {
	case *ast.StructType:
		isEmptyStruct := n.Fields == nil || n.Fields.NumFields() < 1
		if isEmptyStruct {
			return nil // skip empty structs
		}

		w.usedTagNbr = map[int]bool{}
		w.usedTagName = map[string]bool{}
		for _, f := range n.Fields.List {
			if f.Tag != nil {
				w.checkTaggedField(f)
			}
		}
	}

	return w
}

const (
	keyASN1         = "asn1"
	keyBSON         = "bson"
	keyDatastore    = "datastore"
	keyDefault      = "default"
	keyJSON         = "json"
	keyMapstructure = "mapstructure"
	keyProperties   = "properties"
	keyProtobuf     = "protobuf"
	keyRequired     = "required"
	keyTOML         = "toml"
	keyURL          = "url"
	keyValidate     = "validate"
	keyXML          = "xml"
	keyYAML         = "yaml"
)

func (w lintStructTagRule) checkTagNameIfNeed(tag *structTag) (string, bool) {
	isUnnamedTag := tag.Name == "" || tag.Name == "-"
	if isUnnamedTag {
		return "", true
	}

	switch tag.Key {
	case keyBSON, keyJSON, keyXML, keyYAML, keyProtobuf:
	default:
		return "", true
	}

	tagName := w.getTagName(tag)
	if tagName == "" {
		return "", true // No tag name found
	}

	// We concat the key and name as the mapping key here
	// to allow the same tag name in different tag type.
	key := tag.Key + ":" + tagName
	if _, ok := w.usedTagName[key]; ok {
		return fmt.Sprintf("duplicated tag name %q", tagName), false
	}

	w.usedTagName[key] = true

	return "", true
}

func (lintStructTagRule) getTagName(tag *structTag) string {
	switch tag.Key {
	case keyProtobuf:
		for _, option := range tag.Options {
			if tagKey, tagValue, found := strings.Cut(option, "="); found && tagKey == "name" {
				return tagValue
			}
		}
		return "" // protobuf tag lacks 'name' option
	default:
		return tag.Name
	}
}

// checkTaggedField checks the tag of the given field.
// precondition: the field has a tag
func (w lintStructTagRule) checkTaggedField(f *ast.Field) {
	if len(f.Names) > 0 && !f.Names[0].IsExported() {
		w.addFailure(f, "tag on not-exported field "+f.Names[0].Name)
	}

	tags, err := parseStructTags(f.Tag.Value[1 : len(f.Tag.Value)-1])
	if err != nil || tags == nil {
		w.addFailure(f.Tag, "malformed tag")
		return
	}

	for _, tag := range tags {
		if msg, ok := w.checkTagNameIfNeed(tag); !ok {
			w.addFailureWithTagKey(f.Tag, msg, tag.Key)
		}

		switch key := tag.Key; key {
		case keyASN1:
			msg, ok := w.checkASN1Tag(f.Type, tag)
			if !ok {
				w.addFailureWithTagKey(f.Tag, msg, key)
			}
		case keyBSON:
			msg, ok := w.checkBSONTag(tag.Options)
			if !ok {
				w.addFailureWithTagKey(f.Tag, msg, key)
			}
		case keyDatastore:
			msg, ok := w.checkDatastoreTag(tag.Options)
			if !ok {
				w.addFailureWithTagKey(f.Tag, msg, key)
			}
		case keyDefault:
			if !w.typeValueMatch(f.Type, tag.Name) {
				w.addFailureWithTagKey(f.Tag, "type mismatch between field type and default value type", key)
			}
		case keyJSON:
			msg, ok := w.checkJSONTag(tag.Name, tag.Options)
			if !ok {
				w.addFailureWithTagKey(f.Tag, msg, key)
			}
		case keyMapstructure:
			msg, ok := w.checkMapstructureTag(tag.Options)
			if !ok {
				w.addFailureWithTagKey(f.Tag, msg, key)
			}
		case keyProperties:
			msg, ok := w.checkPropertiesTag(f.Type, tag.Options)
			if !ok {
				w.addFailureWithTagKey(f.Tag, msg, key)
			}
		case keyProtobuf:
			msg, ok := w.checkProtobufTag(tag)
			if !ok {
				w.addFailureWithTagKey(f.Tag, msg, key)
			}
		case keyRequired:
			if tag.Name != "true" && tag.Name != "false" {
				w.addFailureWithTagKey(f.Tag, "required should be \"true\" or \"false\"", key)
			}
		case keyTOML:
			msg, ok := w.checkTOMLTag(tag.Options)
			if !ok {
				w.addFailureWithTagKey(f.Tag, msg, key)
			}
		case keyURL:
			msg, ok := w.checkURLTag(tag.Options)
			if !ok {
				w.addFailureWithTagKey(f.Tag, msg, key)
			}
		case keyValidate:
			opts := append([]string{tag.Name}, tag.Options...)
			msg, ok := w.checkValidateTag(opts)
			if !ok {
				w.addFailureWithTagKey(f.Tag, msg, key)
			}
		case keyXML:
			msg, ok := w.checkXMLTag(tag.Options)
			if !ok {
				w.addFailureWithTagKey(f.Tag, msg, key)
			}
		case keyYAML:
			msg, ok := w.checkYAMLTag(tag.Options)
			if !ok {
				w.addFailureWithTagKey(f.Tag, msg, key)
			}
		default:
			// unknown key
		}
	}
}

func (w lintStructTagRule) checkASN1Tag(t ast.Expr, tag *structTag) (string, bool) {
	checkList := append(tag.Options, tag.Name)
	for _, opt := range checkList {
		switch opt {
		case "application", "explicit", "generalized", "ia5", "omitempty", "optional", "set", "utf8":
			continue
		}

		if msg, ok := w.checkCompoundANS1Option(opt, t); !ok {
			return msg, false
		}
	}

	return "", true
}

func (w lintStructTagRule) checkCompoundANS1Option(opt string, t ast.Expr) (string, bool) {
	key, value, _ := strings.Cut(opt, ":")
	switch key {
	case "tag":
		number, err := strconv.Atoi(value)
		if err != nil {
			return fmt.Sprintf("tag must be a number but is %q", value), false
		}
		if w.usedTagNbr[number] {
			return fmt.Sprintf("duplicated tag number %v", number), false
		}
		w.usedTagNbr[number] = true
	case "default":
		if !w.typeValueMatch(t, value) {
			return "type mismatch between field type and default value type", false
		}
	default:
		if w.isUserDefined(keyASN1, opt) {
			return "", true
		}
		return fmt.Sprintf("unknown option %q", opt), false
	}

	return "", true
}

func (w lintStructTagRule) checkDatastoreTag(options []string) (string, bool) {
	for _, opt := range options {
		switch opt {
		case "flatten", "noindex", "omitempty":
			continue
		default:
			if w.isUserDefined(keyDatastore, opt) {
				continue
			}
			return fmt.Sprintf("unknown option %q", opt), false
		}
	}

	return "", true
}

func (w lintStructTagRule) checkBSONTag(options []string) (string, bool) {
	for _, opt := range options {
		switch opt {
		case "inline", "minsize", "omitempty":
			continue
		default:
			if w.isUserDefined(keyBSON, opt) {
				continue
			}
			return fmt.Sprintf("unknown option %q", opt), false
		}
	}

	return "", true
}

func (w lintStructTagRule) checkJSONTag(name string, options []string) (string, bool) {
	for _, opt := range options {
		switch opt {
		case "omitempty", "string":
			continue
		case "":
			// special case for JSON key "-"
			if name != "-" {
				return "option can not be empty", false
			}
		case "omitzero":
			if w.isAtLeastGo124 {
				continue
			}
			return "prior Go 1.24, option \"omitzero\" is unsupported", false
		default:
			if w.isUserDefined(keyJSON, opt) {
				continue
			}
			return fmt.Sprintf("unknown option %q", opt), false
		}
	}

	return "", true
}

func (w lintStructTagRule) checkMapstructureTag(options []string) (string, bool) {
	for _, opt := range options {
		switch opt {
		case "omitempty", "reminder", "squash":
			continue
		default:
			if w.isUserDefined(keyMapstructure, opt) {
				continue
			}
			return fmt.Sprintf("unknown option %q", opt), false
		}
	}

	return "", true
}

func (w lintStructTagRule) checkPropertiesTag(t ast.Expr, options []string) (string, bool) {
	if len(options) == 0 {
		return "", true
	}

	seenOptions := map[string]bool{}
	for _, opt := range options {
		key, value, found := strings.Cut(opt, "=")
		if !found {
			return fmt.Sprintf("unknown or malformed option %q", opt), false
		}

		if seenOptions[key] {
			return fmt.Sprintf("duplicated option %q", key), false
		}
		seenOptions[key] = true

		switch key {
		case "default":
			if !w.typeValueMatch(t, value) {
				return "type mismatch between field type and default value type", false
			}
		case "layout":
			if gofmt(t) != "time.Time" {
				return "layout option is only applicable to fields of type time.Time", false
			}
		default:
			if w.isUserDefined(keyProperties, opt) {
				continue
			}
			return fmt.Sprintf("unknown or malformed option %q", opt), false
		}
	}

	return "", true
}

func (w lintStructTagRule) checkProtobufTag(tag *structTag) (string, bool) {
	// check name
	switch tag.Name {
	case "bytes", "fixed32", "fixed64", "group", "varint", "zigzag32", "zigzag64":
		// do nothing
	default:
		return fmt.Sprintf("invalid tag name %q", tag.Name), false
	}

	return w.checkProtobufOptions(tag.Options)
}

func (w lintStructTagRule) checkProtobufOptions(options []string) (string, bool) {
	seenOptions := map[string]bool{}
	hasName := false
	for _, opt := range options {
		opt := strings.Split(opt, "=")[0]

		if number, err := strconv.Atoi(opt); err == nil {
			_, alreadySeen := w.usedTagNbr[number]
			if alreadySeen {
				return fmt.Sprintf("duplicated tag number %v", number), false
			}
			w.usedTagNbr[number] = true
			continue // option is an integer
		}

		switch opt {
		case "name", "json":
			if seenOptions[opt] {
				return fmt.Sprintf("duplicated option %q", opt), false
			}
			seenOptions[opt] = true
			hasName = hasName || opt == "name"
			continue
		case "opt", "proto3", "rep", "req":
			if seenOptions[opt] {
				return fmt.Sprintf("duplicated option %q", opt), false
			}
			seenOptions[opt] = true
			continue
		default:
			if w.isUserDefined(keyProtobuf, opt) {
				continue
			}
			return fmt.Sprintf("unknown option %q", opt), false
		}
	}

	if !hasName {
		return `mandatory option "name" not found`, false
	}

	return "", true
}

func (w lintStructTagRule) checkTOMLTag(options []string) (string, bool) {
	for _, opt := range options {
		switch opt {
		case "omitempty":
			continue
		default:
			if w.isUserDefined(keyTOML, opt) {
				continue
			}
			return fmt.Sprintf("unknown option %q", opt), false
		}
	}

	return "", true
}

func (w lintStructTagRule) checkURLTag(options []string) (string, bool) {
	var delimiter = ""
	for _, opt := range options {
		switch opt {
		case "int", "omitempty", "numbered", "brackets":
			continue
		case "unix", "unixmilli", "unixnano": // TODO : check that the field is of type time.Time
			continue
		case "comma", "semicolon", "space":
			if delimiter == "" {
				delimiter = opt
				continue
			}
			return fmt.Sprintf("can not set both %q and %q as delimiters", opt, delimiter), false
		default:
			if w.isUserDefined(keyURL, opt) {
				continue
			}
			return fmt.Sprintf("unknown option %q", opt), false
		}
	}

	return "", true
}

func (w lintStructTagRule) checkValidateTag(options []string) (string, bool) {
	previousOption := ""
	seenKeysOption := false
	for _, opt := range options {
		switch opt {
		case "keys":
			if previousOption != "dive" {
				return `option "keys" must follow a "dive" option`, false
			}
			seenKeysOption = true
		case "endkeys":
			if !seenKeysOption {
				return `option "endkeys" without a previous "keys" option`, false
			}
			seenKeysOption = false
		default:
			parts := strings.Split(opt, "|")
			for _, p := range parts {
				if msg, ok := w.checkValidateOption(p); !ok {
					return msg, false
				}
			}
		}
		previousOption = opt
	}

	return "", true
}

func (w lintStructTagRule) checkValidateOption(opt string) (string, bool) {
	key := strings.Split(opt, "=")[0]
	if validateOptions[key] {
		return "", true
	}
	if w.isUserDefined(keyValidate, key) {
		return "", true
	}
	return fmt.Sprintf("unknown option %q", opt), false
}

func (w lintStructTagRule) checkXMLTag(options []string) (string, bool) {
	for _, opt := range options {
		switch opt {
		case "any", "attr", "cdata", "chardata", "comment", "innerxml", "omitempty", "typeattr":
			continue
		default:
			if w.isUserDefined(keyXML, opt) {
				continue
			}
			return fmt.Sprintf("unknown option %q", opt), false
		}
	}

	return "", true
}

func (w lintStructTagRule) checkYAMLTag(options []string) (string, bool) {
	for _, opt := range options {
		switch opt {
		case "flow", "inline", "omitempty":
			continue
		default:
			if w.isUserDefined(keyYAML, opt) {
				continue
			}
			return fmt.Sprintf("unknown option %q", opt), false
		}
	}

	return "", true
}

func (lintStructTagRule) typeValueMatch(t ast.Expr, val string) bool {
	tID, ok := t.(*ast.Ident)
	if !ok {
		return true
	}

	typeMatches := true
	switch tID.Name {
	case "bool":
		typeMatches = val == "true" || val == "false"
	case "float32", "float64":
		_, err := strconv.ParseFloat(val, 64)
		typeMatches = err == nil
	case "int":
		_, err := strconv.ParseInt(val, 10, 64)
		typeMatches = err == nil
	case "string":
	case "nil":
	default:
		// unchecked type
	}

	return typeMatches
}

func (w lintStructTagRule) addFailureWithTagKey(n ast.Node, msg, tagKey string) {
	w.addFailure(n, fmt.Sprintf("%s in %s tag", msg, tagKey))
}

func (w lintStructTagRule) addFailure(n ast.Node, msg string) {
	w.onFailure(lint.Failure{
		Node:       n,
		Failure:    msg,
		Confidence: 1,
	})
}

func (w lintStructTagRule) isUserDefined(key, opt string) bool {
	if w.userDefined == nil {
		return false
	}

	options := w.userDefined[key]
	for _, o := range options {
		if opt == o {
			return true
		}
	}
	return false
}

// structTag is a parsed key:"name,options" struct tag pair.
type structTag struct {
	Key     string
	Name    string
	Options []string
}

// parseStructTags parses the raw text of a struct tag (without surrounding quotes).
// It mimics the strictness of reflect.StructTag lookups: any syntax problem yields an error.
func parseStructTags(tag string) ([]*structTag, error) {
	var tags []*structTag
	hasTag := tag != ""

	for tag != "" {
		// Skip leading space.
		i := 0
		for i < len(tag) && tag[i] == ' ' {
			i++
		}
		tag = tag[i:]
		if tag == "" {
			break
		}

		// Scan to colon. A space, a quote or a control character is a syntax error.
		i = 0
		for i < len(tag) && tag[i] > ' ' && tag[i] != ':' && tag[i] != '"' && tag[i] != 0x7f {
			i++
		}
		if i == 0 {
			return nil, fmt.Errorf("bad syntax for struct tag key")
		}
		if i+1 >= len(tag) || tag[i] != ':' {
			return nil, fmt.Errorf("bad syntax for struct tag pair")
		}
		if tag[i+1] != '"' {
			return nil, fmt.Errorf("bad syntax for struct tag value")
		}
		key := tag[:i]
		tag = tag[i+1:]

		// Scan quoted string to find value.
		i = 1
		for i < len(tag) && tag[i] != '"' {
			if tag[i] == '\\' {
				i++
			}
			i++
		}
		if i >= len(tag) {
			return nil, fmt.Errorf("bad syntax for struct tag value")
		}
		qvalue := tag[:i+1]
		tag = tag[i+1:]

		value, err := strconv.Unquote(qvalue)
		if err != nil {
			return nil, fmt.Errorf("bad syntax for struct tag value")
		}

		res := strings.Split(value, ",")
		name := res[0]
		options := res[1:]
		if len(options) == 0 {
			options = nil
		}

		tags = append(tags, &structTag{Key: key, Name: name, Options: options})
	}

	if hasTag && len(tags) == 0 {
		return nil, nil
	}
	return tags, nil
