package rule

import (
	"fmt"
	"go/ast"
	"go/token"

	"revive/lint"
)

// RangeValAddress lints
type RangeValAddress struct{}

// Name returns the rule name.
func (*RangeValAddress) Name() string {
	return "range-val-address"
}

// Apply applies the rule to given file.
func (*RangeValAddress) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure

	if file.Pkg.IsAtLeastGoVersion("go1.22") {
		return failures
	}

	walker := rangeValAddress{
		file: file,
		onFailure: func(failure lint.Failure) {
			failures = append(failures, failure)
		},
	}

	ast.Walk(walker, file.AST)

	return failures
}

type rangeValAddress struct {
	file      *lint.File
	onFailure func(lint.Failure)
}

func (w rangeValAddress) Visit(node ast.Node) ast.Visitor {
	n, ok := node.(*ast.RangeStmt)
	if !ok {
		return w
	}

	variables := map[string]struct{}{}

	if key, ok := n.Key.(*ast.Ident); ok {
		variables[key.Name] = struct{}{}
	}

	value, ok := n.Value.(*ast.Ident)
	if ok {
		variables[value.Name] = struct{}{}
	}

	if len(variables) == 0 {
		return w
	}

	ast.Walk(rangeBodyVisitor{
		variables: variables,
		onFailure: w.onFailure,
	}, n.Body)

	return w
}

type rangeBodyVisitor struct {
	variables map[string]struct{}
	onFailure func(lint.Failure)
}

func (bw rangeBodyVisitor) Visit(node ast.Node) ast.Visitor {
	asgmt, ok := node.(*ast.AssignStmt)
	if !ok {
		return bw
	}

	for _, exp := range asgmt.Lhs {
		e, ok := exp.(*ast.IndexExpr)
		if !ok {
			continue
		}
		if bw.isAccessingRangeVariableAddress(e.Index) { // e.g. a[&value]...
			bw.onFailure(bw.newFailure(e.Index))
		}
	}

	for _, exp := range asgmt.Rhs {
		switch e := exp.(type) {
		case *ast.UnaryExpr: // e.g. ...&value, ...&value.id
			if bw.isAccessingRangeVariableAddress(e) {
				bw.onFailure(bw.newFailure(e))
			}
		case *ast.CallExpr:
			if fun, ok := e.Fun.(*ast.Ident); ok && fun.Name == "append" { // e.g. ...append(arr, &value)
				for _, v := range e.Args {
					if bw.isAccessingRangeVariableAddress(v) { // e.g. ...append(arr, &value)
						bw.onFailure(bw.newFailure(v))
					}
				}
			}
		case *ast.CompositeLit: // e.g. ...map[address]int{&value: rangeIndex}
			for _, v := range e.Elts {
				kv, ok := v.(*ast.KeyValueExpr)
				if !ok {
					continue
				}

				if bw.isAccessingRangeVariableAddress(kv.Key) { // e.g. ...map[address]int{&value: rangeIndex}
					bw.onFailure(bw.newFailure(kv.Key))
				}

				if bw.isAccessingRangeVariableAddress(kv.Value) { // e.g. ...map[int]address{rangeIndex: &value}
					bw.onFailure(bw.newFailure(kv.Value))
				}
			}
		}
	}
	return bw
}

func (bw rangeBodyVisitor) isAccessingRangeVariableAddress(exp ast.Expr) bool {
	u, ok := exp.(*ast.UnaryExpr)
	if !ok {
		return false
	}

	if u.Op != token.AND {
		return false
	}

	v, ok := u.X.(*ast.Ident)
	if !ok {
		var s *ast.SelectorExpr
		s, ok = u.X.(*ast.SelectorExpr)
		if !ok {
			return false
		}
		v, ok = s.X.(*ast.Ident)
		if !ok {
			return false
		}
	}

	_, ok = bw.variables[v.Name]
	return ok
}

func (bw rangeBodyVisitor) newFailure(node ast.Node) lint.Failure {
	name := gofmt(node)
	if u, ok := node.(*ast.UnaryExpr); ok {
		switch x := u.X.(type) {
		case *ast.Ident:
			name = x.Name
		case *ast.SelectorExpr:
			if id, ok := x.X.(*ast.Ident); ok {
				name = id.Name
			}
		}
	}
	return lint.Failure{
		Node:       node,
		Confidence: 1,
		Failure:    fmt.Sprintf("suspicious assignment of '%s'. range-loop variables always have the same address", name),
	}
}
