		if !ok {
			return false
		}
		v, ok = s.X.(*ast.Ident)
		if !ok {
			return false
		}
	}

	_, ok = bw.variables[v.Name]
	return ok
}

func (bw rangeBodyVisitor) newFailure(node ast.Node) lint.Failure {
	name := gofmt(node)
	if u, ok := node.(*ast.UnaryExpr); ok {
		switch x := u.X.(type) {
		case *ast.Ident:
			name = x.Name
		case *ast.SelectorExpr:
			if id, ok := x.X.(*ast.Ident); ok {
				name = id.Name
			}
		}
	}
	return lint.Failure{
		Node:       node,
		Confidence: 1,
		Failure:    fmt.Sprintf("suspicious assignment of '%s'. range-loop variables always have the same address", name),
	}
}
