package rule

import (
	"fmt"
	"go/ast"
	"go/types"

	"revive/lint"
)

// RangeValInClosureRule warns if range value is used in a closure dispatched as goroutine.
type RangeValInClosureRule struct{}

// Name returns the rule name.
func (*RangeValInClosureRule) Name() string {
	return "range-val-in-closure"
}

// Apply applies the rule to given file.
func (*RangeValInClosureRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure

	if file.Pkg.IsAtLeastGoVersion("go1.22") {
		return failures
	}

	walker := rangeValInClosure{
		file: file,
		onFailure: func(failure lint.Failure) {
			failures = append(failures, failure)
		},
	}

	ast.Walk(walker, file.AST)

	return failures
}

type rangeValInClosure struct {
	file      *lint.File
	onFailure func(lint.Failure)
}

func (w rangeValInClosure) Visit(node ast.Node) ast.Visitor {
	// Find the variables updated by the loop statement.
	var vars []*ast.Ident
	addVar := func(expr ast.Expr) {
		if id, ok := expr.(*ast.Ident); ok {
			vars = append(vars, id)
		}
	}
	var body *ast.BlockStmt
	switch n := node.(type) {
	case *ast.RangeStmt:
		body = n.Body
		addVar(n.Key)
		addVar(n.Value)
	case *ast.ForStmt:
		body = n.Body
		switch post := n.Post.(type) {
		case *ast.AssignStmt:
			// e.g. for p = head; p != nil; p = p.next
			for _, lhs := range post.Lhs {
				addVar(lhs)
			}
		case *ast.IncDecStmt:
			// e.g. for i := 0; i < n; i++
			addVar(post.X)
		}
	}
	if vars == nil {
		return w
	}

	// Inspect a go or defer statement
	// if it's the last one in the loop body.
	// (We give up if there are following statements,
	// because it's hard to prove go isn't followed by wait,
	// or defer by return.)
	if len(body.List) == 0 {
		return w
	}

	var last *ast.CallExpr
	switch s := body.List[len(body.List)-1].(type) {
	case *ast.GoStmt:
		last = s.Call
	case *ast.DeferStmt:
		last = s.Call
	default:
		return w
	}

	lit, ok := last.Fun.(*ast.FuncLit)
	if !ok {
		return w
	}

	if lit.Type == nil {
		// Not referring to a variable (e.g. struct field name)
		return w
	}

	var inspector func(node ast.Node) bool
	inspector = func(node ast.Node) bool {
		kv, ok := node.(*ast.KeyValueExpr)
		if ok {
			// do not check identifiers acting as key in key-value expressions (see issue #637)
			ast.Inspect(kv.Value, inspector)
			return false
		}
		id, ok := node.(*ast.Ident)
		if !ok || id.Obj == nil {
			return true
		}

		if w.file.Pkg.TypesInfo() != nil {
			if _, ok := w.file.Pkg.TypesInfo().Uses[id].(*types.Var); !ok {
				return true
			}
		}

		for _, v := range vars {
			if v.Obj == id.Obj {
				w.onFailure(lint.Failure{
					Confidence: 1,
					Failure:    fmt.Sprintf("loop variable %v captured by func literal", id.Name),
					Node:       id,
				})
			}
		}
		return true
	}
	ast.Inspect(lit.Body, inspector)
	return w
}
