package rule

import (
	"go/ast"

	"revive/lint"
)

// UseWaitGroupGoRule spots wg.Add/go/wg.Done patterns that can be replaced by wg.Go.
type UseWaitGroupGoRule struct{}

// Name returns the rule name.
func (*UseWaitGroupGoRule) Name() string {
	return "use-waitgroup-go"
}

// Apply applies the rule to given file.
func (*UseWaitGroupGoRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	if !file.Pkg.IsAtLeastGoVersion("go1.25") {
		return nil
	}

	var failures []lint.Failure
	onFailure := func(failure lint.Failure) {
		failures = append(failures, failure)
	}

	w := &lintUseWaitGroupGo{onFailure: onFailure}
	ast.Walk(w, file.AST)
	return failures
}

type lintUseWaitGroupGo struct {
	onFailure func(lint.Failure)
}

func (w *lintUseWaitGroupGo) Visit(node ast.Node) ast.Visitor {
	block, ok := node.(*ast.BlockStmt)
	if !ok {
		return w
	}

	var wgAdd *ast.CallExpr
	for _, stmt := range block.List {
		switch s := stmt.(type) {
		case *ast.ExprStmt:
			call, ok := s.X.(*ast.CallExpr)
			if !ok {
				continue
			}
			if wgAdd == nil && isWgMethodCall(call, "Add") {
				wgAdd = call
			}
		case *ast.GoStmt:
			if wgAdd == nil {
				continue
			}
			lit, ok := s.Call.Fun.(*ast.FuncLit)
			if !ok {
				continue
			}
			if !bodyCallsWgDone(lit.Body) {
				continue
			}
			w.onFailure(lint.Failure{
				Category:   "style",
				Confidence: 1,
				Node:       wgAdd,
				Failure:    "replace wg.Add()...go {...wg.Done()...} with wg.Go(...)",
			})
			wgAdd = nil
		}
	}

	return w
}

func isWgMethodCall(call *ast.CallExpr, method string) bool {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return false
	}
	return isIdent(sel.X, "wg") && sel.Sel.Name == method
}

func bodyCallsWgDone(body *ast.BlockStmt) bool {
	calls := pick(body, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		return ok && isWgMethodCall(call, "Done")
	})
	return len(calls) > 0
}
