package rule

import (
	"go/ast"
	"go/token"

	"revive/lint"
)

// UselessBreak lint rule.
type UselessBreak struct{}

// Name returns the rule name.
func (*UselessBreak) Name() string {
	return "useless-break"
}

// Apply applies the rule to given file.
func (*UselessBreak) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure

	onFailure := func(failure lint.Failure) {
		failures = append(failures, failure)
	}

	astFile := file.AST
	w := &lintUselessBreak{onFailure, false}
	ast.Walk(w, astFile)
	return failures
}

type lintUselessBreak struct {
	onFailure  func(lint.Failure)
	inLoopBody bool
}

func (w *lintUselessBreak) Visit(node ast.Node) ast.Visitor {
	switch v := node.(type) {
	case *ast.ForStmt:
		w.inLoopBody = true
		ast.Walk(w, v.Body)
		w.inLoopBody = false
		return nil
	case *ast.RangeStmt:
		w.inLoopBody = true
		ast.Walk(w, v.Body)
		w.inLoopBody = false
		return nil
	case *ast.CommClause:
		w.inspectCaseStatements(v.Body)
		return nil
	case *ast.CaseClause:
		w.inspectCaseStatements(v.Body)
		return nil
	}
	return w
}

func (w *lintUselessBreak) inspectCaseStatements(stmts []ast.Stmt) {
	if len(stmts) == 0 {
		return
	}
	for i, s := range stmts {
		isLast := i == len(stmts)-1
		b, ok := s.(*ast.BranchStmt)
		if !ok || b.Tok != token.BREAK || b.Label != nil || !isLast {
			ast.Walk(w, s)
			continue
		}
		msg := "useless break in case clause"
		if w.inLoopBody {
			msg += " (WARN: this break statement affects this switch or select statement and not the loop enclosing it)"
		}
		w.onFailure(lint.Failure{
			Confidence: 1,
			Node:       b,
			Failure:    msg,
		})
	}
}
