package rule

import (
	"fmt"
	"go/ast"
	"go/token"
	"strconv"
	"strings"

	"revive/lint"
)

// UnsecureURLSchemeRule warns on the use of http URLs.
type UnsecureURLSchemeRule struct{}

// Name returns the rule name.
func (*UnsecureURLSchemeRule) Name() string {
	return "unsecure-url-scheme"
}

// Apply applies the rule to given file.
func (*UnsecureURLSchemeRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure

	w := &lintUnsecureURLScheme{
		onFailure: func(failure lint.Failure) {
			failures = append(failures, failure)
		},
	}
	ast.Walk(w, file.AST)

	return failures
}

type lintUnsecureURLScheme struct {
	onFailure func(lint.Failure)
}

var localHostPrefixes = []string{
	"http://localhost",
	"http://127.0.0.1",
	"http://0.0.0.0",
	"http://::1",
}

func (w *lintUnsecureURLScheme) Visit(n ast.Node) ast.Visitor {
	lit, ok := n.(*ast.BasicLit)
	if !ok || lit.Kind != token.STRING {
		return w
	}

	value, err := strconv.Unquote(lit.Value)
	if err != nil {
		return w
	}

	if !strings.HasPrefix(value, "http://") || len(value) == len("http://") {
		return w
	}

	for _, prefix := range localHostPrefixes {
		if strings.HasPrefix(value, prefix) {
			return w
		}
	}

	w.onFailure(lint.Failure{
		Confidence: 1,
		Node:       lit,
		Failure:    fmt.Sprintf("prefer secure protocol https over http in %s", lit.Value),
	})

	return w
}
