package rule

import (
	"go/ast"
	"go/token"

	"revive/lint"
)

// UselessFallthroughRule spots fallthrough statements that can be removed.
type UselessFallthroughRule struct{}

// Name returns the rule name.
func (*UselessFallthroughRule) Name() string {
	return "useless-fallthrough"
}

// Apply applies the rule to given file.
func (*UselessFallthroughRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure

	onFailure := func(failure lint.Failure) {
		failures = append(failures, failure)
	}

	w := &lintUselessFallthrough{onFailure: onFailure, cmap: file.CommentMap()}
	ast.Walk(w, file.AST)
	return failures
}

type lintUselessFallthrough struct {
	onFailure func(lint.Failure)
	cmap      ast.CommentMap
}

func (w *lintUselessFallthrough) Visit(node ast.Node) ast.Visitor {
	switchStmt, ok := node.(*ast.SwitchStmt)
	if !ok {
		return w
	}

	clauses := switchStmt.Body.List
	for i, stmt := range clauses {
		cc, ok := stmt.(*ast.CaseClause)
		if !ok || len(cc.Body) != 1 {
			continue
		}

		branch, ok := cc.Body[0].(*ast.BranchStmt)
		if !ok || branch.Tok != token.FALLTHROUGH {
			continue
		}

		if i+1 >= len(clauses) {
			continue // last clause
		}

		next, ok := clauses[i+1].(*ast.CaseClause)
		if !ok || next.List == nil {
			continue // next clause is the default one
		}

		if w.hasLeadingComment(branch) {
			continue // the fallthrough is documented
		}

		w.onFailure(lint.Failure{
			Confidence: 1,
			Node:       branch,
			Category:   "style",
			Failure:    `this "fallthrough" can be removed by consolidating this case clause with the next one`,
		})
	}

	return w
}

func (w *lintUselessFallthrough) hasLeadingComment(n ast.Node) bool {
	for _, cg := range w.cmap[n] {
		if cg.Pos() < n.Pos() {
			return true
		}
	}
	return false
}
EOF
