package rule

import (
	"fmt"
	"go/ast"
	"strings"

	"revive/lint"
)

// UseFmtPrintRule lints calls to the built-in print and println functions.
type UseFmtPrintRule struct{}

// Name returns the rule name.
func (*UseFmtPrintRule) Name() string {
	return "use-fmt-print"
}

// Apply applies the rule to given file.
func (*UseFmtPrintRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure

	w := &lintUseFmtPrint{
		onFailure: func(failure lint.Failure) {
			failures = append(failures, failure)
		},
	}

	ast.Walk(w, file.AST)

	return failures
}

type lintUseFmtPrint struct {
	onFailure func(lint.Failure)
}

func (w *lintUseFmtPrint) Visit(n ast.Node) ast.Visitor {
	ce, ok := n.(*ast.CallExpr)
	if !ok {
		return w
	}

	ident, ok := ce.Fun.(*ast.Ident)
	if !ok {
		return w
	}

	var replacement string
	switch ident.Name {
	case "print":
		replacement = "fmt.Fprint"
	case "println":
		replacement = "fmt.Fprintln"
	default:
		return w
	}

	args := make([]string, 0, len(ce.Args))
	for _, arg := range ce.Args {
		args = append(args, gofmt(arg))
	}

	w.onFailure(lint.Failure{
		Confidence: 1,
		Node:       ce,
		Category:   "bad practice",
		Failure:    fmt.Sprintf("avoid using built-in function %q, replace it by \"%s(os.Stderr, %s)\"", ident.Name, replacement, strings.Join(args, ", ")),
	})

	return w
}
