// checkArgument checks the literal form of an argument and returns its value if it is an integer literal.
func (w *lintTimeDate) checkArgument(arg ast.Expr, name string) *int {
	lit, ok := arg.(*ast.BasicLit)
	if !ok {
		return nil
	}

	switch lit.Kind {
	case token.INT:
		return w.checkIntArgument(lit, name)
	case token.FLOAT:
		return w.checkFloatArgument(lit, name)
	}
