	v := int(value)

	lower := strings.ToLower(raw)
	switch {
	case strings.HasPrefix(lower, "0x"):
		w.decimalFailure(lit, name, "hexadecimal notation found", v, raw, 0.8)
	case strings.HasPrefix(lower, "0b"):
		w.decimalFailure(lit, name, "binary notation found", v, raw, 0.8)
	case strings.HasPrefix(lower, "0o"):
		w.decimalFailure(lit, name, "octal notation found", v, raw, 0.8)
	case strings.Contains(raw, "_"):
		digits := strings.ReplaceAll(raw, "_", "")
		if strings.HasPrefix(digits, "0") && len(digits) > 1 {
			w.decimalFailure(lit, name, "octal notation found", v, raw, 0.8)
		} else {
			w.decimalFailure(lit, name, "alternative notation found", v, raw, 0.8)
