					Confidence: 1,
					Node:       lit,
					Failure:    fmt.Sprintf("use decimal digits for time.Date %s argument: octal notation with padding zeroes found: choose between %d and %d (decimal value of %d octal value)", name, asDecimal, v, asDecimal),
