	})
}

func (w *lintTimeDate) checkRanges(args []ast.Expr, values []*int) {
	year, month, day, hour, minute, sec, nsec := values[0], values[1], values[2], values[3], values[4], values[5], values[6]

	if month != nil {
		switch {
		case *month == 0:
			w.rangeFailure(args[1], "time.Date month argument should not be zero", 1)
		case *month < 1 || *month > 12:
			w.rangeFailure(args[1], fmt.Sprintf("time.Date month argument should be between 1 and 12: %d", *month), 0.8)
		}
	}

	if day != nil {
		switch {
		case *day == 0:
			w.rangeFailure(args[2], "time.Date day argument should not be zero", 1)
		case *day < 1 || *day > 31:
			w.rangeFailure(args[2], fmt.Sprintf("time.Date day argument should be between 1 and 31: %d", *day), 0.8)
		case month != nil && *month >= 1 && *month <= 12:
			m := time.Month(*month)
			if year != nil {
				maxDays := daysIn(m, *year)
				if *day > maxDays {
					if m == time.February {
						w.rangeFailure(args[2], fmt.Sprintf("time.Date day argument is %d, but %s %d has only %d days", *day, m, *year, maxDays), 0.8)
					} else {
						w.rangeFailure(args[2], fmt.Sprintf("time.Date day argument is %d, but %s has only %d days", *day, m, maxDays), 0.8)
					}
				}
			} else if m != time.February {
				maxDays := daysIn(m, 2001)
				if *day > maxDays {
					w.rangeFailure(args[2], fmt.Sprintf("time.Date day argument is %d, but %s has only %d days", *day, m, maxDays), 0.8)
				}
			}
		}
	}

	if hour != nil && (*hour < 0 || *hour > 23) {
		w.rangeFailure(args[3], fmt.Sprintf("time.Date hour argument should be between 0 and 23: %d", *hour), 0.8)
	}
	if minute != nil && (*minute < 0 || *minute > 59) {
		w.rangeFailure(args[4], fmt.Sprintf("time.Date minute argument should be between 0 and 59: %d", *minute), 0.8)
	}
	if sec != nil && (*sec < 0 || *sec > 60) {
		w.rangeFailure(args[5], fmt.Sprintf("time.Date second argument should be between 0 and 60: %d", *sec), 0.8)
	}
	if nsec != nil && (*nsec < 0 || *nsec > 999999999) {
		w.rangeFailure(args[6], fmt.Sprintf("time.Date nanosecond argument should be between 0 and 999999999: %d", *nsec), 0.8)
	}
}

func (w *lintTimeDate) rangeFailure(node ast.Node, msg string, confidence float64) {
	w.onFailure(lint.Failure{
		Category:   "time",
		Confidence: confidence,
		Node:       node,
		Failure:    msg,
	})
}

func daysIn(m time.Month, year int) int {
	return time.Date(year, m+1, 0, 0, 0, 0, 0, time.UTC).Day()
}
