		}
		selectIDs := func(n ast.Node) bool {
			id, ok := n.(*ast.Ident)
			if !ok {
				return false
			}

			_, isRangeID := w.rangeIDs[id.Obj]
			_, isReturnID := w.returnIDs[id.Obj]

